# 3) API / 웹소켓 타입 정의

아래 타입은 TypeScript 기준입니다.

## 3-1. 공통 타입

```ts
// src/shared/types/common.ts
export type UUID = string;
export type ISODateTime = string;

export interface ApiResponse<T> {
  success: boolean;
  data: T;
  error: ApiError | null;
}

export interface ApiError {
  code: string;
  message: string;
  details?: unknown;
}

export interface PageMeta {
  total?: number;
  page?: number;
  pageSize?: number;
}
```

## 3-2. 상담원/세션 타입

```ts
// src/features/agent-session/types.ts
export type AgentRole = 'agent' | 'supervisor' | 'admin';

export type AgentStatusCode =
  | 'LOGGED_OUT'
  | 'AVAILABLE'
  | 'RINGING'
  | 'TALKING'
  | 'AFTER_CALL_WORK'
  | 'BREAK'
  | 'MEAL'
  | 'TRAINING'
  | 'SYSTEM_PAUSED'
  | 'MANUAL_PAUSED';

export interface AgentProfile {
  agentId: UUID;
  tenantId: UUID;
  agentCode: string;
  agentName: string;
  extension: string;
  role: AgentRole;
  defaultQueueId?: UUID | null;
}

export interface AgentSessionInfo {
  agent: AgentProfile;
  currentStatus: AgentStatusCode;
  reasonCode?: string | null;
  loginAt?: ISODateTime | null;
  todayStats: {
    totalCalls: number;
    answeredCalls: number;
    missedCalls: number;
    talkSeconds: number;
    acwSeconds: number;
  };
}
```

