## 3-6. WebSocket 이벤트 타입

```ts
// src/features/realtime/event-types.ts
import { ActiveCall } from '@/features/calls/types';
import { CustomerSummary } from '@/features/customers/types';
import { AgentStatusCode } from '@/features/agent-session/types';
import { QueueSummary } from '@/features/queues/types';
import { ISODateTime, UUID } from '@/shared/types/common';

export interface WsEnvelope<TType extends string, TPayload> {
  type: TType;
  timestamp: ISODateTime;
  payload: TPayload;
}

export type CallCreatedEvent = WsEnvelope<
  'call.created',
  {
    call: ActiveCall;
  }
>;

export type CallUpdatedEvent = WsEnvelope<
  'call.updated',
  {
    callId: UUID;
    linkedid: string;
    patch: Partial<ActiveCall>;
  }
>;

export type CallEndedEvent = WsEnvelope<
  'call.ended',
  {
    callId: UUID;
    linkedid: string;
    endedAt: ISODateTime;
    talkSeconds: number;
    resultCode?: string | null;
  }
>;

export type ScreenPopCustomerEvent = WsEnvelope<
  'screenpop.customer',
  {
    callId: UUID;
    linkedid: string;
    customer: CustomerSummary | null;
  }
>;

export type AgentStatusChangedEvent = WsEnvelope<
  'agent.status.changed',
  {
    agentId: UUID;
    statusCode: AgentStatusCode;
    reasonCode?: string | null;
  }
>;

export type QueueSummaryUpdatedEvent = WsEnvelope<
  'queue.summary.updated',
  {
    queue: QueueSummary;
  }
>;

export type RealtimeEvent =
  | CallCreatedEvent
  | CallUpdatedEvent
  | CallEndedEvent
  | ScreenPopCustomerEvent
  | AgentStatusChangedEvent
  | QueueSummaryUpdatedEvent;
```

