## 4-4. 상담원 상태 패널

```tsx
// src/features/agent-status/components/AgentStatusPanel.tsx
import { useState } from 'react';
import { AgentStatusCode } from '@/features/agent-session/types';
import { useAgentSession } from '@/features/agent-session/hooks';
import { useChangeAgentStatus } from '@/features/agent-status/hooks';

const STATUS_OPTIONS: AgentStatusCode[] = [
  'AVAILABLE',
  'BREAK',
  'MEAL',
  'TRAINING',
  'AFTER_CALL_WORK',
];

export function AgentStatusPanel() {
  const { data } = useAgentSession();
  const changeStatus = useChangeAgentStatus();
  const [selected, setSelected] = useState<AgentStatusCode>('AVAILABLE');
  const [reasonCode, setReasonCode] = useState('');

  const agentId = data?.agent.agentId;

  const onSubmit = async () => {
    if (!agentId) return;
    await changeStatus.mutateAsync({
      agentId,
      body: {
        statusCode: selected,
        reasonCode: reasonCode || undefined,
      },
    });
  };

  return (
    <section className="rounded-xl bg-white p-4 shadow-sm">
      <h2 className="mb-3 text-sm font-semibold">상태 변경</h2>

      <div className="space-y-2">
        {STATUS_OPTIONS.map((status) => (
          <label key={status} className="flex items-center gap-2">
            <input
              type="radio"
              name="agent-status"
              checked={selected === status}
              onChange={() => setSelected(status)}
            />
            <span>{status}</span>
          </label>
        ))}
      </div>

      <select
        className="mt-3 w-full rounded border p-2"
        value={reasonCode}
        onChange={(e) => setReasonCode(e.target.value)}
      >
        <option value="">사유 없음</option>
        <option value="SHORT_BREAK">짧은 휴식</option>
        <option value="MEAL_TIME">식사</option>
        <option value="TRAINING_SESSION">교육</option>
      </select>

      <button
        className="mt-3 w-full rounded bg-slate-900 px-3 py-2 text-white"
        onClick={onSubmit}
        disabled={changeStatus.isPending}
      >
        상태 적용
      </button>
    </section>
  );
}
```

