# 6) WebSocket 클라이언트 골격

## 6-1. 클라이언트

```ts
// src/features/realtime/ws-client.ts
import { RealtimeEvent } from './event-types';

type EventHandler = (event: RealtimeEvent) => void;

export class AgentWsClient {
  private ws: WebSocket | null = null;
  private handlers = new Set<EventHandler>();

  connect(token: string) {
    const protocol = window.location.protocol === 'https:' ? 'wss' : 'ws';
    const url = `${protocol}://${window.location.host}/ws/agent?token=${encodeURIComponent(token)}`;

    this.ws = new WebSocket(url);

    this.ws.onmessage = (message) => {
      try {
        const event = JSON.parse(message.data) as RealtimeEvent;
        this.handlers.forEach((handler) => handler(event));
      } catch (error) {
        console.error('Invalid WS event', error);
      }
    };

    this.ws.onclose = () => {
      // 간단 재연결 예시
      setTimeout(() => this.connect(token), 3000);
    };
  }

  disconnect() {
    this.ws?.close();
    this.ws = null;
  }

  subscribe(handler: EventHandler) {
    this.handlers.add(handler);
    return () => this.handlers.delete(handler);
  }
}
```

## 6-2. 이벤트 반영

```ts
// src/features/realtime/event-handlers.ts
import { QueryClient } from '@tanstack/react-query';
import { RealtimeEvent } from './event-types';
import { ActiveCall } from '@/features/calls/types';

export function handleRealtimeEvent(queryClient: QueryClient, event: RealtimeEvent) {
  switch (event.type) {
    case 'call.created': {
      queryClient.setQueryData<ActiveCall[]>(['active-calls'], (prev = []) => {
        const exists = prev.some((c) => c.callId === event.payload.call.callId);
        return exists ? prev : [event.payload.call, ...prev];
      });
      break;
    }

    case 'call.updated': {
      queryClient.setQueryData<ActiveCall[]>(['active-calls'], (prev = []) =>
        prev.map((call) =>
          call.callId === event.payload.callId
            ? { ...call, ...event.payload.patch }
            : call,
        ),
      );
      break;
    }

    case 'call.ended': {
      queryClient.setQueryData<ActiveCall[]>(['active-calls'], (prev = []) =>
        prev.filter((call) => call.callId !== event.payload.callId),
      );
      break;
    }

    case 'queue.summary.updated': {
      queryClient.setQueryData(['queue-summary'], event.payload.queue);
      break;
    }

    case 'screenpop.customer': {
      queryClient.setQueryData(['screenpop-customer'], event.payload.customer);
      break;
    }

    default:
      break;
  }
}
```

## 6-3. Provider

```tsx
// src/app/providers/RealtimeProvider.tsx
import { PropsWithChildren, useEffect, useMemo } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { AgentWsClient } from '@/features/realtime/ws-client';
import { handleRealtimeEvent } from '@/features/realtime/event-handlers';

export function RealtimeProvider({ children }: PropsWithChildren) {
  const queryClient = useQueryClient();
  const wsClient = useMemo(() => new AgentWsClient(), []);

  useEffect(() => {
    const token = localStorage.getItem('accessToken');
    if (!token) return;

    wsClient.connect(token);
    const unsubscribe = wsClient.subscribe((event) => {
      handleRealtimeEvent(queryClient, event);
    });

    return () => {
      unsubscribe();
      wsClient.disconnect();
    };
  }, [queryClient, wsClient]);

  return <>{children}</>;
}
```

