```ts
export interface WsEnvelope<TType extends string, TPayload> {
  type: TType;
  timestamp: string;
  payload: TPayload;
}
```

```ts
export type AgentWsEvent =
  | WsEnvelope<'call.created', ActiveCallSession>
  | WsEnvelope<'call.updated', Partial<ActiveCallSession> & { callId: string }>
  | WsEnvelope<'call.ended', { callId: string; endedAt: string; talkSeconds: number }>
  | WsEnvelope<'screenpop.customer', {
      callId: string;
      customerId?: string;
      customerName?: string;
      grade?: string;
      phoneNumber?: string;
    }>
  | WsEnvelope<'agent.status.changed', {
      agentId: string;
      statusCode: string;
      reasonCode?: string;
    }>
  | WsEnvelope<'queue.summary.updated', {
      queueName: string;
      waitingCount: number;
      availableAgents: number;
      talkingAgents: number;
    }>
  | WsEnvelope<'ui.mode.changed', {
      agentId: string;
      mode: UiMode;
      switchedAt: string;
    }>
  | WsEnvelope<'ui.policy.updated', {
      agentId: string;
      allowModeSwitch: boolean;
      allowedModes: UiMode[];
    }>;
```

