## 6) API 타입 정의 예시

문서 기준 REST / WebSocket 이벤트 구조를 그대로 프론트 타입으로 고정하는 것이 좋습니다. fileciteturn1file8

```ts
export type SessionStatus =
  | "NEW"
  | "IVR"
  | "QUEUED"
  | "RINGING_AGENT"
  | "TALKING"
  | "HOLD"
  | "TRANSFERRING"
  | "AFTER_CALL_WORK"
  | "ENDED";

export interface AgentSession {
  agentId: string;
  agentName: string;
  extension: string;
  statusCode: string;
  role: "agent" | "supervisor" | "admin";
}

export interface ActiveCall {
  callId: string;
  linkedid: string;
  ani: string;
  dnis?: string;
  queueName?: string;
  customerId?: string;
  customerName?: string;
  customerGrade?: string;
  sessionStatus: SessionStatus;
  waitSeconds: number;
  talkSeconds: number;
  answeredAt?: string;
}

export interface CustomerSummary {
  customerId: string;
  customerName: string;
  grade?: string;
  phones: Array<{
    phoneNumber: string;
    isPrimary: boolean;
  }>;
  recentCalls: number;
}

export type AgentWsEvent =
  | {
      type: "call.created";
      payload: Pick<ActiveCall, "callId" | "linkedid" | "ani" | "queueName" | "sessionStatus">;
    }
  | {
      type: "call.updated";
      payload: Partial<ActiveCall> & { callId: string };
    }
  | {
      type: "call.ended";
      payload: { callId: string; endedAt: string; talkSeconds: number };
    }
  | {
      type: "screenpop.customer";
      payload: CustomerSummary;
    }
  | {
      type: "agent.status.changed";
      payload: { agentId: string; statusCode: string };
    }
  | {
      type: "queue.summary.updated";
      payload: { queueName: string; waitingCount: number; availableAgents: number };
    };
```

