## 8) WebSocket 클라이언트

```ts
// src/shared/socket/client.ts
import type { AppWsEvent } from './eventBus';

type Listener = (event: AppWsEvent) => void;

class SocketClient {
  private ws?: WebSocket;
  private listeners = new Set<Listener>();

  connect(token: string) {
    const base = import.meta.env.VITE_WS_BASE_URL ?? 'ws://localhost:3000/ws/agent';
    this.ws = new WebSocket(`${base}?token=${encodeURIComponent(token)}`);

    this.ws.onmessage = (message) => {
      try {
        const parsed = JSON.parse(message.data) as AppWsEvent;
        this.listeners.forEach((listener) => listener(parsed));
      } catch (error) {
        console.error('Invalid WS message', error);
      }
    };
  }

  disconnect() {
    this.ws?.close();
    this.ws = undefined;
  }

  subscribe(listener: Listener) {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }
}

export const socketClient = new SocketClient();
```

