## 9) React Query와 WebSocket 연결 방식

핵심은 **WS 수신 → Query Cache 갱신**입니다.  
즉, 서버 푸시를 별도 전역 상태에 쌓기보다, React Query 캐시를 최신화합니다.

```tsx
// src/app/providers/SocketProvider.tsx
import { PropsWithChildren, useEffect } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { socketClient } from '@/shared/socket/client';
import type { AppWsEvent } from '@/shared/socket/eventBus';
import { queryKeys } from '@/shared/api/queryKeys';

export function SocketProvider({ children }: PropsWithChildren) {
  const qc = useQueryClient();

  useEffect(() => {
    const token = localStorage.getItem('accessToken');
    if (!token) return;

    socketClient.connect(token);

    const unsubscribe = socketClient.subscribe((event: AppWsEvent) => {
      switch (event.type) {
        case 'call.created':
        case 'call.updated':
        case 'call.ended':
          qc.invalidateQueries({ queryKey: queryKeys.calls.active() });
          break;
        case 'screenpop.customer':
          qc.invalidateQueries({ queryKey: queryKeys.calls.active() });
          break;
        case 'agent.status.changed':
          qc.invalidateQueries({ queryKey: queryKeys.auth.me() });
          break;
        case 'queue.summary.updated':
          qc.invalidateQueries({ queryKey: queryKeys.queues.summary() });
          break;
      }
    });

    return () => {
      unsubscribe();
      socketClient.disconnect();
    };
  }, [qc]);

  return <>{children}</>;
}
```

