## 10) Calls API / Hooks

```ts
// src/features/calls/api.ts
import { http } from '@/shared/api/axios';
import type {
  ActiveCallItem,
  CallDetail,
  SaveCallMemoRequest,
  OriginateCallRequest,
  TransferCallRequest,
} from './rest.types';

export async function getActiveCalls() {
  const { data } = await http.get<ActiveCallItem[]>('/calls/active');
  return data;
}

export async function getCallDetail(callId: string) {
  const { data } = await http.get<CallDetail>(`/calls/${callId}`);
  return data;
}

export async function saveCallMemo(callId: string, payload: SaveCallMemoRequest) {
  const { data } = await http.post(`/calls/${callId}/memo`, payload);
  return data;
}

export async function originateCall(payload: OriginateCallRequest) {
  const { data } = await http.post('/calls/originate', payload);
  return data;
}

export async function transferCall(callId: string, payload: TransferCallRequest) {
  const { data } = await http.post(`/calls/${callId}/transfer`, payload);
  return data;
}

export async function hangupCall(callId: string) {
  const { data } = await http.post(`/calls/${callId}/hangup`);
  return data;
}
```

```ts
// src/features/calls/hooks.ts
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { queryKeys } from '@/shared/api/queryKeys';
import {
  getActiveCalls,
  getCallDetail,
  saveCallMemo,
  originateCall,
  transferCall,
  hangupCall,
} from './api';

export function useActiveCalls() {
  return useQuery({
    queryKey: queryKeys.calls.active(),
    queryFn: getActiveCalls,
    refetchOnWindowFocus: false,
  });
}

export function useCallDetail(callId?: string) {
  return useQuery({
    queryKey: callId ? queryKeys.calls.detail(callId) : ['calls', 'detail', 'empty'],
    queryFn: () => getCallDetail(callId!),
    enabled: !!callId,
  });
}

export function useSaveCallMemo(callId: string) {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (payload: Parameters<typeof saveCallMemo>[1]) => saveCallMemo(callId, payload),
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: queryKeys.calls.detail(callId) });
      qc.invalidateQueries({ queryKey: queryKeys.calls.active() });
    },
  });
}

export function useTransferCall(callId: string) {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (payload: Parameters<typeof transferCall>[1]) => transferCall(callId, payload),
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: queryKeys.calls.active() });
      qc.invalidateQueries({ queryKey: queryKeys.calls.detail(callId) });
    },
  });
}

export function useHangupCall(callId: string) {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: () => hangupCall(callId),
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: queryKeys.calls.active() });
    },
  });
}

export function useOriginateCall() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: originateCall,
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: queryKeys.calls.active() });
    },
  });
}
```

