```ts
import { ApiProperty, ApiPropertyOptional } from '@nestjs/swagger';
import { IsEnum, IsOptional, IsString, MaxLength } from 'class-validator';

export enum AgentStatusCode {
  AVAILABLE = 'AVAILABLE',
  AFTER_CALL_WORK = 'AFTER_CALL_WORK',
  BREAK = 'BREAK',
  MEAL = 'MEAL',
  TRAINING = 'TRAINING',
  MANUAL_PAUSED = 'MANUAL_PAUSED',
}

export class ChangeAgentStatusDto {
  @ApiProperty({
    enum: AgentStatusCode,
    description: '상담원이 변경하려는 목표 상태',
    example: AgentStatusCode.BREAK,
  })
  @IsEnum(AgentStatusCode)
  statusCode!: AgentStatusCode;

  @ApiPropertyOptional({
    description: '상태 변경 사유 코드',
    example: 'RESTROOM',
  })
  @IsOptional()
  @IsString()
  @MaxLength(32)
  reasonCode?: string;

  @ApiPropertyOptional({
    description: '상태 변경 사유 상세 텍스트',
    example: '잠시 자리 비움',
  })
  @IsOptional()
  @IsString()
  @MaxLength(255)
  reasonText?: string;
}
```

