## 4) Controller 예시

### `src/calls/calls.controller.ts`
```ts
import {
  Body,
  Controller,
  Param,
  ParseUUIDPipe,
  Post,
} from '@nestjs/common';
import {
  ApiBearerAuth,
  ApiBody,
  ApiOperation,
  ApiParam,
  ApiTags,
} from '@nestjs/swagger';
import { ChangeAgentStatusDto } from './dto/change-agent-status.dto';
import { SaveCallMemoDto } from './dto/save-call-memo.dto';
import { TransferCallDto } from './dto/transfer-call.dto';
import { HangupCallDto } from './dto/hangup-call.dto';
import { CallsService } from './calls.service';

@ApiTags('CTI Calls')
@ApiBearerAuth()
@Controller('api/v1')
export class CallsController {
  constructor(private readonly callsService: CallsService) {}

  @Post('agents/:agentId/status')
  @ApiOperation({ summary: '상담원 상태 변경' })
  @ApiParam({ name: 'agentId', description: '상담원 ID(UUID)' })
  @ApiBody({ type: ChangeAgentStatusDto })
  async changeAgentStatus(
    @Param('agentId', new ParseUUIDPipe()) agentId: string,
    @Body() dto: ChangeAgentStatusDto,
  ) {
    return this.callsService.changeAgentStatus(agentId, dto);
  }

  @Post('calls/:callId/memo')
  @ApiOperation({ summary: '통화 메모 및 후처리 저장' })
  @ApiParam({ name: 'callId', description: '콜 ID(UUID)' })
  @ApiBody({ type: SaveCallMemoDto })
  async saveCallMemo(
    @Param('callId', new ParseUUIDPipe()) callId: string,
    @Body() dto: SaveCallMemoDto,
  ) {
    return this.callsService.saveCallMemo(callId, dto);
  }

  @Post('calls/:callId/transfer')
  @ApiOperation({ summary: '호 전환 요청' })
  @ApiParam({ name: 'callId', description: '콜 ID(UUID)' })
  @ApiBody({ type: TransferCallDto })
  async transferCall(
    @Param('callId', new ParseUUIDPipe()) callId: string,
    @Body() dto: TransferCallDto,
  ) {
    return this.callsService.transferCall(callId, dto);
  }

  @Post('calls/:callId/hangup')
  @ApiOperation({ summary: '호 종료 요청' })
  @ApiParam({ name: 'callId', description: '콜 ID(UUID)' })
  @ApiBody({ type: HangupCallDto })
  async hangupCall(
    @Param('callId', new ParseUUIDPipe()) callId: string,
    @Body() dto: HangupCallDto,
  ) {
    return this.callsService.hangupCall(callId, dto);
  }
}
