## 5) Service 레벨 최소 검증 규칙

### `changeAgentStatus`
```ts
async changeAgentStatus(agentId: string, dto: ChangeAgentStatusDto) {
  const agent = await this.agentRepo.findById(agentId);
  if (!agent) {
    throw new NotFoundException('상담원을 찾을 수 없습니다.');
  }

  if (
    [ 'BREAK', 'MEAL', 'TRAINING', 'MANUAL_PAUSED' ].includes(dto.statusCode) &&
    !dto.reasonCode
  ) {
    throw new BadRequestException('pause 계열 상태는 reasonCode가 필요합니다.');
  }

  await this.agentStatusService.changeStatus(agentId, dto);

  return {
    success: true,
    data: {
      agentId,
      statusCode: dto.statusCode,
      reasonCode: dto.reasonCode ?? null,
      changedAt: new Date().toISOString(),
    },
    error: null,
  };
}
```

### `saveCallMemo`
```ts
async saveCallMemo(callId: string, dto: SaveCallMemoDto) {
  const call = await this.callRepo.findById(callId);
  if (!call) {
    throw new NotFoundException('콜을 찾을 수 없습니다.');
  }

  if (dto.memoType === 'acw' && dto.isFinal && !dto.resultCode) {
    throw new BadRequestException('최종 후처리 저장 시 resultCode는 필수입니다.');
  }

  const memo = await this.memoRepo.create({
    callId,
    memoType: dto.memoType,
    resultCode: dto.resultCode ?? null,
    subResultCode: dto.subResultCode ?? null,
    memoText: dto.memoText ?? null,
    isFinal: dto.isFinal,
  });

  return {
    success: true,
    data: {
      memoId: memo.memoId,
      callId,
      savedAt: memo.createdAt,
    },
    error: null,
  };
}
```

### `transferCall`
```ts
async transferCall(callId: string, dto: TransferCallDto) {
  const call = await this.callRepo.findActiveById(callId);
  if (!call) {
    throw new BadRequestException('현재 활성 통화가 아닙니다.');
  }

  if (call.sessionStatus !== 'TALKING') {
    throw new BadRequestException('전환은 TALKING 상태에서만 가능합니다.');
  }

  const transfer = await this.transferRepo.createRequested({
    callId,
    transferType: dto.transferType,
    targetType: dto.targetType,
    target: dto.target,
    note: dto.note ?? null,
  });

  await this.pbxCommandService.transferCall(call, dto);

  return {
    success: true,
    data: {
      transferId: transfer.transferId,
      callId,
      transferStatus: 'REQUESTED',
    },
    error: null,
  };
}
```

### `hangupCall`
```ts
async hangupCall(callId: string, dto: HangupCallDto) {
  const call = await this.callRepo.findById(callId);
  if (!call) {
    throw new NotFoundException('콜을 찾을 수 없습니다.');
  }

  if (call.sessionStatus === 'ENDED') {
    return {
      success: true,
      data: {
        callId,
        hangupRequested: false,
        alreadyEnded: true,
      },
      error: null,
    };
  }

  await this.pbxCommandService.hangupCall(call, dto.hangupReason);

  return {
    success: true,
    data: {
      callId,
      hangupRequested: true,
    },
    error: null,
  };
}
```

