## 9) transfer API Swagger DTO 정식화

기존 문서에 `/calls/{callId}/transfer` 요청 예시는 이미 있고, `transferType`, `targetType`, `target` 구조를 사용하고 있습니다. 이걸 NestJS Swagger DTO로 정식화하면 됩니다. fileciteturn0file2L325-L347

### Request DTO

```ts
import { ApiProperty } from '@nestjs/swagger';
import { IsEnum, IsOptional, IsString } from 'class-validator';

export enum TransferType {
  BLIND = 'blind',
  ATTENDED = 'attended',
  QUEUE = 'queue',
  EXTERNAL = 'external',
}

export enum TransferTargetType {
  EXTENSION = 'extension',
  QUEUE = 'queue',
  PHONE = 'phone',
}

export class CallTransferRequestDto {
  @ApiProperty({ enum: TransferType, example: TransferType.ATTENDED })
  @IsEnum(TransferType)
  transferType: TransferType;

  @ApiProperty({ enum: TransferTargetType, example: TransferTargetType.EXTENSION })
  @IsEnum(TransferTargetType)
  targetType: TransferTargetType;

  @ApiProperty({ example: '1002' })
  @IsString()
  target: string;

  @ApiProperty({ example: '고객 VIP 이슈로 2차 상담 이관', required: false })
  @IsOptional()
  @IsString()
  reason?: string;
}
```

