import {
  ConnectedSocket,
  MessageBody,
  OnGatewayConnection,
  OnGatewayInit,
  SubscribeMessage,
  WebSocketGateway,
  WebSocketServer,
} from '@nestjs/websockets';
import { Logger } from '@nestjs/common';
import { Server, Socket } from 'socket.io';

@WebSocketGateway({
  namespace: '/ws/agent',
  cors: { origin: '*' },
})
export class CtiGateway implements OnGatewayInit, OnGatewayConnection {
  @WebSocketServer()
  server!: Server;

  private readonly logger = new Logger(CtiGateway.name);

  afterInit(): void {
    this.logger.log('CTI WebSocket initialized');
  }

  handleConnection(client: Socket): void {
    this.logger.log(`WebSocket connected: ${client.id}`);
  }

  @SubscribeMessage('subscribe.agent')
  onSubscribeAgent(
    @ConnectedSocket() client: Socket,
    @MessageBody() body: { agentId?: string; tenantId?: string },
  ): void {
    if (body?.tenantId) {
      client.join(`tenant:${body.tenantId}`);
    }
    if (body?.agentId) {
      client.join(`agent:${body.agentId}`);
    }
  }

  broadcastToTenant(tenantId: string, event: string, payload: unknown): void {
    this.server.to(`tenant:${tenantId}`).emit(event, payload);
  }

  broadcastToAgent(agentId: string, event: string, payload: unknown): void {
    this.server.to(`agent:${agentId}`).emit(event, payload);
  }

  broadcastGlobal(event: string, payload: unknown): void {
    this.server.emit(event, payload);
  }
}
```

