```ts
import { AmiMessage } from './ami.types';

export function parseAmiPacket(packet: string): AmiMessage {
  const result: AmiMessage = {};
  const lines = packet.split('\r\n').filter(Boolean);

  for (const line of lines) {
    const idx = line.indexOf(':');
    if (idx < 0) continue;

    const key = line.slice(0, idx).trim();
    const value = line.slice(idx + 1).trim();
    result[key] = value;
  }

  return result;
}
