## 10. 실제 TCP 기반 AMI Client

### `src/asterisk/ami/ami.tcp-client.ts`

```ts
import {
  Injectable,
  Logger,
  OnModuleDestroy,
  OnModuleInit,
} from '@nestjs/common';
import * as net from 'net';
import { parseAmiPacket } from './ami.parser';
import { AMI_EVENT_SEPARATOR, AMI_INTERESTING_EVENTS } from './ami.constants';
import { AmiMessage } from './ami.types';
import { SessionEngineService } from '../engine/session-engine.service';

@Injectable()
export class AmiTcpClient implements OnModuleInit, OnModuleDestroy {
  private readonly logger = new Logger(AmiTcpClient.name);
  private socket: net.Socket | null = null;
  private buffer = '';
  private reconnectTimer: NodeJS.Timeout | null = null;
  private actionCounter = 0;
  private isLoggedIn = false;

  constructor(private readonly sessionEngine: SessionEngineService) {}

  onModuleInit(): void {
    this.connect();
  }

  onModuleDestroy(): void {
    if (this.reconnectTimer) clearTimeout(this.reconnectTimer);
    this.socket?.destroy();
  }

  private connect(): void {
    const host = process.env.AMI_HOST ?? '127.0.0.1';
    const port = Number(process.env.AMI_PORT ?? 5038);

    this.logger.log(`Connecting to AMI ${host}:${port}`);

    this.socket = net.createConnection({ host, port }, () => {
      this.logger.log('AMI TCP connected');
    });

    this.socket.on('data', (chunk: Buffer) => {
      this.buffer += chunk.toString('utf8');
      this.flushPackets();
    });

    this.socket.on('error', (error) => {
      this.logger.error(`AMI socket error: ${error.message}`);
    });

    this.socket.on('close', () => {
      this.logger.warn('AMI socket closed');
      this.isLoggedIn = false;
      this.scheduleReconnect();
    });
  }

  private flushPackets(): void {
    while (this.buffer.includes(AMI_EVENT_SEPARATOR)) {
      const idx = this.buffer.indexOf(AMI_EVENT_SEPARATOR);
      const packet = this.buffer.slice(0, idx);
      this.buffer = this.buffer.slice(idx + AMI_EVENT_SEPARATOR.length);

      if (!packet.trim()) continue;

      const message = parseAmiPacket(packet);
      this.handleMessage(message).catch((err) => {
        this.logger.error(`AMI packet handling failed: ${err.message}`, err.stack);
      });
    }
  }

  private async handleMessage(message: AmiMessage): Promise<void> {
    if (message.Response === 'Success' && /Authentication accepted/i.test(message.Message ?? '')) {
      this.isLoggedIn = true;
      this.logger.log('AMI login success');
      return;
    }

    if (message.AsteriskCallManager && !this.isLoggedIn) {
      this.login();
      return;
    }

    const eventName = message.Event;
    if (!eventName) return;

    if (!AMI_INTERESTING_EVENTS.has(eventName)) {
      return;
    }

    await this.sessionEngine.processEvent({
      eventName,
      linkedid: message.Linkedid || message.LinkedId || message.Linkedid?.trim(),
      uniqueid: message.Uniqueid || message.UniqueId,
      eventTime: new Date(),
      payload: message,
    });
  }

  private login(): void {
    const username = process.env.AMI_USERNAME ?? 'cti_middleware';
    const secret = process.env.AMI_SECRET ?? 'STRONG_AMI_PASSWORD';

    this.sendRaw([
      'Action: Login',
      `Username: ${username}`,
      `Secret: ${secret}`,
      'Events: on',
      '',
      '',
    ].join('\r\n'));
  }

  private scheduleReconnect(): void {
    if (this.reconnectTimer) return;

    this.reconnectTimer = setTimeout(() => {
      this.reconnectTimer = null;
      this.connect();
    }, 3000);
  }

  sendAction(action: Record<string, string>): string {
    const actionId = `act-${Date.now()}-${++this.actionCounter}`;

    const lines = [`ActionID: ${actionId}`, ...Object.entries(action).map(([k, v]) => `${k}: ${v}`)];
    this.sendRaw(lines.join('\r\n') + '\r\n\r\n');
    return actionId;
  }

  private sendRaw(payload: string): void {
    if (!this.socket || this.socket.destroyed) {
      throw new Error('AMI socket is not connected');
    }
    this.socket.write(payload);
  }
}
