import { Injectable } from '@nestjs/common';
import { AmiTcpClient } from './ami.tcp-client';

@Injectable()
export class AmiCommandService {
  constructor(private readonly amiTcpClient: AmiTcpClient) {}

  originate(extension: string, targetNumber: string, context = 'from-internal'): string {
    return this.amiTcpClient.sendAction({
      Action: 'Originate',
      Channel: `PJSIP/${extension}`,
      Context: context,
      Exten: targetNumber,
      Priority: '1',
      CallerID: extension,
      Async: 'true',
      Variable: `__ORIGINATE_MODE=clicktocall,__TARGET_NUMBER=${targetNumber}`,
    });
  }

  hangup(channel: string): string {
    return this.amiTcpClient.sendAction({
      Action: 'Hangup',
      Channel: channel,
    });
  }

  blindTransfer(channel: string, targetExten: string, context = 'from-internal'): string {
    return this.amiTcpClient.sendAction({
      Action: 'Redirect',
      Channel: channel,
      Context: context,
      Exten: targetExten,
      Priority: '1',
    });
  }

  attendedTransfer(channel: string, targetExten: string): string {
    return this.amiTcpClient.sendAction({
      Action: 'Atxfer',
      Channel: channel,
      Exten: targetExten,
      Context: 'from-internal',
      Priority: '1',
    });
  }
}
