## 13. Normalizer 유틸

### `src/asterisk/engine/event-normalizer.util.ts`

```ts
export function normalizePhone(input?: string | null): string | null {
  if (!input) return null;
  const onlyDigits = input.replace(/[^\d]/g, '');
  return onlyDigits || null;
}

export function detectDirection(channel?: string, context?: string): 'inbound' | 'outbound' | 'internal' {
  const c = channel ?? '';
  const ctx = context ?? '';

  if (ctx.includes('inbound') || c.includes('trunk-provider')) return 'inbound';
  if (ctx.includes('outbound') || c.includes('Local/')) return 'outbound';
  return 'internal';
}

export function extractExtension(channel?: string): string | null {
  if (!channel) return null;
  const match = channel.match(/(?:PJSIP|SIP|Local)\/([0-9A-Za-z_-]+)/);
  return match?.[1] ?? null;
}

export function isAgentChannel(channel?: string): boolean {
  if (!channel) return false;
  return /PJSIP\/\d+|SIP\/\d+|Local\/\d+@from-queue/i.test(channel);
}

export function computeSeconds(start?: Date | null, end?: Date | null): number {
  if (!start || !end) return 0;
  return Math.max(0, Math.floor((end.getTime() - start.getTime()) / 1000));
}
