import { Injectable } from '@nestjs/common';
import { Prisma, CallSession } from '@prisma/client';
import { PrismaService } from '../../prisma/prisma.service';

@Injectable()
export class CallSessionRepository {
  constructor(private readonly prisma: PrismaService) {}

  async findByLinkedid(tenantId: string, linkedid: string): Promise<CallSession | null> {
    return this.prisma.callSession.findFirst({
      where: { tenantId, linkedid },
    });
  }

  async upsertSession(
    tenantId: string,
    linkedid: string,
    createData: Prisma.CallSessionCreateInput,
    updateData: Prisma.CallSessionUpdateInput,
  ): Promise<CallSession> {
    const existing = await this.findByLinkedid(tenantId, linkedid);
    if (existing) {
      return this.prisma.callSession.update({
        where: { callId: existing.callId },
        data: updateData,
      });
    }

    return this.prisma.callSession.create({
      data: createData,
    });
  }

  async upsertLeg(
    tenantId: string,
    uniqueid: string,
    data: {
      callId: string;
      linkedid: string;
      legType: string;
      channelName?: string | null;
      bridgedChannelName?: string | null;
      endpoint?: string | null;
      agentId?: string | null;
      stateCode?: string | null;
      dialStatus?: string | null;
      startedAt: Date;
      bridgedAt?: Date | null;
      endedAt?: Date | null;
      durationSeconds?: number;
      disposition?: string | null;
      parentUniqueid?: string | null;
    },
  ): Promise<void> {
    const existing = await this.prisma.callLeg.findFirst({
      where: { tenantId, uniqueid },
    });

    if (existing) {
      await this.prisma.callLeg.update({
        where: { legId: existing.legId },
        data: {
          channelName: data.channelName ?? undefined,
          bridgedChannelName: data.bridgedChannelName ?? undefined,
          endpoint: data.endpoint ?? undefined,
          agentId: data.agentId ?? undefined,
          stateCode: data.stateCode ?? undefined,
          dialStatus: data.dialStatus ?? undefined,
          bridgedAt: data.bridgedAt ?? undefined,
          endedAt: data.endedAt ?? undefined,
          durationSeconds: data.durationSeconds ?? undefined,
          disposition: data.disposition ?? undefined,
        },
      });
      return;
    }

    await this.prisma.callLeg.create({
      data: {
        tenantId,
        uniqueid,
        callId: data.callId,
        linkedid: data.linkedid,
        legType: data.legType,
        channelName: data.channelName,
        bridgedChannelName: data.bridgedChannelName,
        endpoint: data.endpoint,
        agentId: data.agentId,
        stateCode: data.stateCode,
        dialStatus: data.dialStatus,
        startedAt: data.startedAt,
        bridgedAt: data.bridgedAt,
        endedAt: data.endedAt,
        durationSeconds: data.durationSeconds ?? 0,
        disposition: data.disposition,
        parentUniqueid: data.parentUniqueid,
      },
    });
  }

  async findActiveSessions(tenantId: string) {
    return this.prisma.callSession.findMany({
      where: {
        tenantId,
        sessionStatus: {
          not: 'ENDED',
        },
      },
      orderBy: { startedAt: 'desc' },
    });
  }
}
