## 15. Queue Summary Service

### `src/asterisk/engine/queue-summary.service.ts`

```ts
import { Injectable } from '@nestjs/common';
import { CallSession } from '@prisma/client';
import { CtiGateway } from '../../websocket/cti.gateway';
import { QueueSummaryRow } from '../ami/ami.types';

@Injectable()
export class QueueSummaryService {
  private readonly queueMap = new Map<string, QueueSummaryRow>();

  constructor(private readonly gateway: CtiGateway) {}

  rebuildFromSessions(tenantId: string, sessions: CallSession[]): void {
    const next = new Map<string, QueueSummaryRow>();

    for (const session of sessions) {
      const queueName = session.queueName;
      if (!queueName) continue;

      const current = next.get(queueName) ?? {
        queueName,
        waitingCount: 0,
        talkingCount: 0,
        ringingCount: 0,
        availableAgents: 0,
        updatedAt: new Date().toISOString(),
      };

      if (session.sessionStatus === 'QUEUED') current.waitingCount += 1;
      if (session.sessionStatus === 'RINGING_AGENT') current.ringingCount += 1;
      if (session.sessionStatus === 'TALKING') current.talkingCount += 1;

      current.updatedAt = new Date().toISOString();
      next.set(queueName, current);
    }

    this.queueMap.clear();
    for (const [key, value] of next.entries()) {
      this.queueMap.set(key, value);
    }

    this.gateway.broadcastToTenant(tenantId, 'queue.summary.updated', {
      queues: this.getAll(),
    });
  }

  getAll(): QueueSummaryRow[] {
    return [...this.queueMap.values()];
  }
}
