## 16. Session Engine 핵심

### `src/asterisk/engine/session-engine.service.ts`

```ts
import { Injectable, Logger } from '@nestjs/common';
import { AmiEventEnvelope } from '../ami/ami.types';
import { RawAmiEventRepository } from '../services/raw-ami-event.repository';
import { CallSessionRepository } from '../services/call-session.repository';
import { QueueEventRepository } from '../services/queue-event.repository';
import { AgentStateRepository } from '../services/agent-state.repository';
import { CtiGateway } from '../../websocket/cti.gateway';
import {
  computeSeconds,
  detectDirection,
  extractExtension,
  isAgentChannel,
  normalizePhone,
} from './event-normalizer.util';

@Injectable()
export class SessionEngineService {
  private readonly logger = new Logger(SessionEngineService.name);
  private readonly tenantId = process.env.DEFAULT_TENANT_ID ?? '00000000-0000-0000-0000-000000000001';

  constructor(
    private readonly rawRepo: RawAmiEventRepository,
    private readonly sessionRepo: CallSessionRepository,
    private readonly queueEventRepo: QueueEventRepository,
    private readonly agentStateRepo: AgentStateRepository,
    private readonly gateway: CtiGateway,
  ) {}

  async processEvent(event: AmiEventEnvelope): Promise<void> {
    const linkedid = event.linkedid || event.payload.Linkedid || event.payload.Uniqueid;
    if (!linkedid) {
      this.logger.warn(`Skip event without linkedid: ${event.eventName}`);
      return;
    }

    let session = await this.sessionRepo.findByLinkedid(this.tenantId, linkedid);

    await this.rawRepo.create(this.tenantId, { ...event, linkedid }, session?.callId);

    switch (event.eventName) {
      case 'Newchannel':
        session = await this.handleNewchannel(linkedid, event);
        break;
      case 'Newstate':
        session = await this.handleNewstate(linkedid, event);
        break;
      case 'QueueCallerJoin':
        session = await this.handleQueueCallerJoin(linkedid, event);
        break;
      case 'QueueCallerLeave':
        session = await this.handleQueueCallerLeave(linkedid, event);
        break;
      case 'AgentCalled':
        session = await this.handleAgentCalled(linkedid, event);
        break;
      case 'AgentConnect':
        session = await this.handleAgentConnect(linkedid, event);
        break;
      case 'AgentComplete':
        session = await this.handleAgentComplete(linkedid, event);
        break;
      case 'BridgeEnter':
        session = await this.handleBridgeEnter(linkedid, event);
        break;
      case 'BridgeLeave':
        session = await this.handleBridgeLeave(linkedid, event);
        break;
      case 'Hold':
        session = await this.handleHold(linkedid, event);
        break;
      case 'Unhold':
        session = await this.handleUnhold(linkedid, event);
        break;
      case 'Hangup':
        session = await this.handleHangup(linkedid, event);
        break;
      case 'BlindTransfer':
        session = await this.handleBlindTransfer(linkedid, event);
        break;
      case 'AttendedTransfer':
        session = await this.handleAttendedTransfer(linkedid, event);
        break;
      case 'DialBegin':
      case 'DialEnd':
      case 'VarSet':
      default:
        session = await this.handleGenericLegUpdate(linkedid, event);
        break;
    }

    if (session) {
      this.gateway.broadcastToTenant(this.tenantId, 'call.updated', {
        callId: session.callId,
        linkedid: session.linkedid,
        sessionStatus: session.sessionStatus,
        queueName: session.queueName,
        primaryAgentId: session.primaryAgentId,
        answeredAt: session.answeredAt,
        endedAt: session.endedAt,
        talkSeconds: session.talkSeconds,
      });

      if (session.primaryAgentId) {
        this.gateway.broadcastToAgent(session.primaryAgentId, 'call.updated', {
          callId: session.callId,
          linkedid: session.linkedid,
          sessionStatus: session.sessionStatus,
        });
      }
    }
  }

  private async handleNewchannel(linkedid: string, event: AmiEventEnvelope) {
    const payload = event.payload;
    const channel = payload.Channel;
    const caller = payload.CallerIDNum || payload.CallerIDNum?.trim() || payload.ConnectedLineNum;
    const dnis = payload.Exten;
    const direction = detectDirection(channel, payload.Context);

    const session = await this.sessionRepo.upsertSession(
      this.tenantId,
      linkedid,
      {
        tenantId: this.tenantId,
        linkedid,
        direction,
        ani: caller ?? null,
        aniNormalized: normalizePhone(caller),
        dnis: dnis ?? null,
        didNumber: dnis ?? null,
        trunkName: payload.Channel ?? null,
        sessionStatus: 'NEW',
        startedAt: event.eventTime,
      },
      {
        ani: caller ?? undefined,
        aniNormalized: normalizePhone(caller) ?? undefined,
        dnis: dnis ?? undefined,
      },
    );

    await this.sessionRepo.upsertLeg(this.tenantId, payload.Uniqueid, {
      callId: session.callId,
      linkedid,
      uniqueid: payload.Uniqueid,
      legType: isAgentChannel(channel) ? 'agent' : direction === 'inbound' ? 'inbound' : 'outbound',
      channelName: channel,
      endpoint: extractExtension(channel),
      stateCode: payload.ChannelStateDesc ?? 'Down',
      startedAt: event.eventTime,
      parentUniqueid: payload.Linkedid && payload.Linkedid !== payload.Uniqueid ? payload.Linkedid : null,
    });

    this.gateway.broadcastToTenant(this.tenantId, 'call.created', {
      callId: session.callId,
      linkedid: session.linkedid,
      ani: session.ani,
      queueName: session.queueName,
      sessionStatus: session.sessionStatus,
    });

    return session;
  }

  private async handleNewstate(linkedid: string, event: AmiEventEnvelope) {
    const payload = event.payload;
    const state = payload.ChannelStateDesc;
    const session = await this.sessionRepo.findByLinkedid(this.tenantId, linkedid);
    if (!session) return null;

    if (state === 'Ringing') {
      return this.sessionRepo.upsertSession(
        this.tenantId,
        linkedid,
        {
          tenantId: this.tenantId,
          linkedid,
          direction: 'inbound',
          sessionStatus: 'RINGING_AGENT',
          startedAt: event.eventTime,
        },
        {
          sessionStatus: 'RINGING_AGENT',
          ringingAt: session.ringingAt ?? event.eventTime,
        },
      );
    }

    if (state === 'Up' && !session.answeredAt) {
      return this.sessionRepo.upsertSession(
        this.tenantId,
        linkedid,
        {
          tenantId: this.tenantId,
          linkedid,
          direction: 'inbound',
          sessionStatus: 'TALKING',
          startedAt: event.eventTime,
        },
        {
          sessionStatus: 'TALKING',
          answeredAt: event.eventTime,
          ringSeconds: computeSeconds(session.ringingAt, event.eventTime),
        },
      );
    }

    return session;
  }

  private async handleQueueCallerJoin(linkedid: string, event: AmiEventEnvelope) {
    const payload = event.payload;
    const queueName = payload.Queue;
    const session = await this.sessionRepo.upsertSession(
      this.tenantId,
      linkedid,
      {
        tenantId: this.tenantId,
        linkedid,
        direction: 'inbound',
        queueName,
        sessionStatus: 'QUEUED',
        startedAt: event.eventTime,
        queuedAt: event.eventTime,
      },
      {
        queueName,
        queuedAt: event.eventTime,
        sessionStatus: 'QUEUED',
      },
    );

    await this.queueEventRepo.create({
      tenantId: this.tenantId,
      callId: session.callId,
      linkedid,
      queueName,
      eventType: 'JOIN',
      eventTime: event.eventTime,
      positionNo: payload.Position ? Number(payload.Position) : null,
      rawPayload: payload,
    });

    return session;
  }

  private async handleQueueCallerLeave(linkedid: string, event: AmiEventEnvelope) {
    const payload = event.payload;
    const queueName = payload.Queue;
    const session = await this.sessionRepo.findByLinkedid(this.tenantId, linkedid);
    if (!session) return null;

    const isAbandon = (payload.Reason ?? '').toUpperCase().includes('ABANDON');

    await this.queueEventRepo.create({
      tenantId: this.tenantId,
      callId: session.callId,
      linkedid,
      queueName,
      eventType: isAbandon ? 'ABANDON' : 'LEAVE',
      eventTime: event.eventTime,
      waitSeconds: computeSeconds(session.queuedAt, event.eventTime),
      rawPayload: payload,
    });

    return this.sessionRepo.upsertSession(
      this.tenantId,
      linkedid,
      {
        tenantId: this.tenantId,
        linkedid,
        direction: 'inbound',
        queueName,
        sessionStatus: 'ENDED',
        startedAt: event.eventTime,
      },
      {
        abandonFlag: isAbandon,
        waitSeconds: computeSeconds(session.queuedAt, event.eventTime),
        sessionStatus: isAbandon ? 'ENDED' : session.sessionStatus,
        endedAt: isAbandon ? event.eventTime : session.endedAt,
        resultCode: isAbandon ? 'ABANDONED' : session.resultCode,
      },
    );
  }

  private async handleAgentCalled(linkedid: string, event: AmiEventEnvelope) {
    const payload = event.payload;
    const queueName = payload.Queue;
    const extension =
      extractExtension(payload.Destination) ||
      extractExtension(payload.Interface) ||
      extractExtension(payload.MemberName);

    const agent = await this.agentStateRepo.findAgentByExtension(this.tenantId, extension);
    const session = await this.sessionRepo.findByLinkedid(this.tenantId, linkedid);
    if (!session) return null;

    await this.queueEventRepo.create({
      tenantId: this.tenantId,
      callId: session.callId,
      linkedid,
      queueName,
      agentId: agent?.agentId,
      eventType: 'AGENT_CALLED',
      eventTime: event.eventTime,
      rawPayload: payload,
    });

    return this.sessionRepo.upsertSession(
      this.tenantId,
      linkedid,
      {
        tenantId: this.tenantId,
        linkedid,
        direction: session.direction,
        queueName: queueName ?? session.queueName ?? undefined,
        sessionStatus: 'RINGING_AGENT',
        startedAt: session.startedAt,
      },
      {
        queueName: queueName ?? undefined,
        primaryAgentId: agent?.agentId ?? undefined,
        ringingAt: session.ringingAt ?? event.eventTime,
        sessionStatus: 'RINGING_AGENT',
      },
    );
  }

  private async handleAgentConnect(linkedid: string, event: AmiEventEnvelope) {
    const payload = event.payload;
    const queueName = payload.Queue;
    const extension =
      extractExtension(payload.MemberName) ||
      extractExtension(payload.Interface) ||
      extractExtension(payload.DestChannel);

    const agent = await this.agentStateRepo.findAgentByExtension(this.tenantId, extension);
    const session = await this.sessionRepo.findByLinkedid(this.tenantId, linkedid);
    if (!session) return null;

    await this.queueEventRepo.create({
      tenantId: this.tenantId,
      callId: session.callId,
      linkedid,
      queueName: queueName ?? session.queueName ?? 'unknown',
      agentId: agent?.agentId,
      eventType: 'AGENT_CONNECT',
      eventTime: event.eventTime,
      waitSeconds: computeSeconds(session.queuedAt, event.eventTime),
      rawPayload: payload,
    });

    if (agent?.agentId) {
      await this.agentStateRepo.markTalking(this.tenantId, agent.agentId, event.eventTime);
    }

    const updated = await this.sessionRepo.upsertSession(
      this.tenantId,
      linkedid,
      {
        tenantId: this.tenantId,
        linkedid,
        direction: session.direction,
        queueName: session.queueName ?? queueName ?? undefined,
        sessionStatus: 'TALKING',
        startedAt: session.startedAt,
      },
      {
        primaryAgentId: agent?.agentId ?? undefined,
        sessionStatus: 'TALKING',
        answeredAt: session.answeredAt ?? event.eventTime,
        waitSeconds: computeSeconds(session.queuedAt, event.eventTime),
        ringSeconds: computeSeconds(session.ringingAt, event.eventTime),
      },
    );

    if (agent?.agentId) {
      this.gateway.broadcastToAgent(agent.agentId, 'screenpop.customer', {
        linkedid,
        phone: updated.ani,
        customerId: updated.customerId,
        customerName: null,
        grade: null,
      });
    }

    return updated;
  }

  private async handleAgentComplete(linkedid: string, event: AmiEventEnvelope) {
    const payload = event.payload;
    const extension = extractExtension(payload.MemberName) || extractExtension(payload.Interface);
    const agent = await this.agentStateRepo.findAgentByExtension(this.tenantId, extension);
    const session = await this.sessionRepo.findByLinkedid(this.tenantId, linkedid);
    if (!session) return null;

    await this.queueEventRepo.create({
      tenantId: this.tenantId,
      callId: session.callId,
      linkedid,
      queueName: payload.Queue ?? session.queueName ?? 'unknown',
      agentId: agent?.agentId,
      eventType: 'AGENT_COMPLETE',
      eventTime: event.eventTime,
      ringSeconds: payload.RingTime ? Number(payload.RingTime) : 0,
      rawPayload: payload,
    });

    if (agent?.agentId) {
      await this.agentStateRepo.markAfterCallWork(this.tenantId, agent.agentId, event.eventTime);
    }

    return this.sessionRepo.upsertSession(
      this.tenantId,
      linkedid,
      {
        tenantId: this.tenantId,
        linkedid,
        direction: session.direction,
        sessionStatus: 'AFTER_CALL_WORK',
        startedAt: session.startedAt,
      },
      {
        sessionStatus: 'AFTER_CALL_WORK',
        acwSeconds: session.acwSeconds,
      },
    );
  }

  private async handleBridgeEnter(linkedid: string, event: AmiEventEnvelope) {
    const session = await this.sessionRepo.findByLinkedid(this.tenantId, linkedid);
    if (!session) return null;

    return this.sessionRepo.upsertSession(
      this.tenantId,
      linkedid,
      {
        tenantId: this.tenantId,
        linkedid,
        direction: session.direction,
        sessionStatus: 'TALKING',
        startedAt: session.startedAt,
      },
      {
        sessionStatus: 'TALKING',
        answeredAt: session.answeredAt ?? event.eventTime,
        talkSeconds: 0,
      },
    );
  }

  private async handleBridgeLeave(linkedid: string, event: AmiEventEnvelope) {
    const session = await this.sessionRepo.findByLinkedid(this.tenantId, linkedid);
    if (!session) return null;

    return this.sessionRepo.upsertSession(
      this.tenantId,
      linkedid,
      {
        tenantId: this.tenantId,
        linkedid,
        direction: session.direction,
        sessionStatus: 'AFTER_CALL_WORK',
        startedAt: session.startedAt,
      },
      {
        sessionStatus: 'AFTER_CALL_WORK',
        talkSeconds: computeSeconds(session.answeredAt, event.eventTime),
      },
    );
  }

  private async handleHold(linkedid: string, event: AmiEventEnvelope) {
    const session = await this.sessionRepo.findByLinkedid(this.tenantId, linkedid);
    if (!session) return null;

    return this.sessionRepo.upsertSession(
      this.tenantId,
      linkedid,
      {
        tenantId: this.tenantId,
        linkedid,
        direction: session.direction,
        sessionStatus: 'HOLD',
        startedAt: session.startedAt,
      },
      {
        sessionStatus: 'HOLD',
      },
    );
  }

  private async handleUnhold(linkedid: string, event: AmiEventEnvelope) {
    const session = await this.sessionRepo.findByLinkedid(this.tenantId, linkedid);
    if (!session) return null;

    return this.sessionRepo.upsertSession(
      this.tenantId,
      linkedid,
      {
        tenantId: this.tenantId,
        linkedid,
        direction: session.direction,
        sessionStatus: 'TALKING',
        startedAt: session.startedAt,
      },
      {
        sessionStatus: 'TALKING',
      },
    );
  }

  private async handleHangup(linkedid: string, event: AmiEventEnvelope) {
    const payload = event.payload;
    const session = await this.sessionRepo.findByLinkedid(this.tenantId, linkedid);
    if (!session) return null;

    if (payload.Uniqueid) {
      await this.sessionRepo.upsertLeg(this.tenantId, payload.Uniqueid, {
        callId: session.callId,
        linkedid,
        uniqueid: payload.Uniqueid,
        legType: isAgentChannel(payload.Channel) ? 'agent' : 'inbound',
        channelName: payload.Channel,
        endpoint: extractExtension(payload.Channel),
        stateCode: 'Hangup',
        startedAt: session.startedAt,
        endedAt: event.eventTime,
        durationSeconds: computeSeconds(session.startedAt, event.eventTime),
        disposition: payload.CauseTxt ?? payload.Cause,
      });
    }

    const ended = await this.sessionRepo.upsertSession(
      this.tenantId,
      linkedid,
      {
        tenantId: this.tenantId,
        linkedid,
        direction: session.direction,
        sessionStatus: 'ENDED',
        startedAt: session.startedAt,
      },
      {
        sessionStatus: 'ENDED',
        endedAt: session.endedAt ?? event.eventTime,
        talkSeconds: computeSeconds(session.answeredAt, event.eventTime),
        waitSeconds: session.waitSeconds || computeSeconds(session.queuedAt, session.answeredAt ?? event.eventTime),
        resultCode: session.abandonFlag ? 'ABANDONED' : 'COMPLETED',
      },
    );

    this.gateway.broadcastToTenant(this.tenantId, 'call.ended', {
      callId: ended.callId,
      linkedid: ended.linkedid,
      endedAt: ended.endedAt,
      talkSeconds: ended.talkSeconds,
    });

    return ended;
  }

  private async handleBlindTransfer(linkedid: string, event: AmiEventEnvelope) {
    const session = await this.sessionRepo.findByLinkedid(this.tenantId, linkedid);
    if (!session) return null;

    return this.sessionRepo.upsertSession(
      this.tenantId,
      linkedid,
      {
        tenantId: this.tenantId,
        linkedid,
        direction: session.direction,
        sessionStatus: 'TRANSFERRING',
        startedAt: session.startedAt,
      },
      {
        transferFlag: true,
        sessionStatus: 'TRANSFERRING',
        resultDetail: 'BLIND_TRANSFER',
      },
    );
  }

  private async handleAttendedTransfer(linkedid: string, event: AmiEventEnvelope) {
    const session = await this.sessionRepo.findByLinkedid(this.tenantId, linkedid);
    if (!session) return null;

    return this.sessionRepo.upsertSession(
      this.tenantId,
      linkedid,
      {
        tenantId: this.tenantId,
        linkedid,
        direction: session.direction,
        sessionStatus: 'TRANSFERRING',
        startedAt: session.startedAt,
      },
      {
        transferFlag: true,
        sessionStatus: 'TRANSFERRING',
        resultDetail: 'ATTENDED_TRANSFER',
      },
    );
  }

  private async handleGenericLegUpdate(linkedid: string, event: AmiEventEnvelope) {
    const payload = event.payload;
    const session = await this.sessionRepo.findByLinkedid(this.tenantId, linkedid);
    if (!session) return null;

    if (payload.Uniqueid) {
      await this.sessionRepo.upsertLeg(this.tenantId, payload.Uniqueid, {
        callId: session.callId,
        linkedid,
        uniqueid: payload.Uniqueid,
        legType: isAgentChannel(payload.Channel) ? 'agent' : session.direction,
        channelName: payload.Channel,
        bridgedChannelName: payload.BridgedChannel,
        endpoint: extractExtension(payload.Channel),
        stateCode: payload.ChannelStateDesc ?? payload.SubEvent ?? event.eventName,
        dialStatus: payload.DialStatus,
        startedAt: session.startedAt,
      });
    }

    return session;
  }
}
