## 17. 실전용 Controller 예시

이건 붙이면 API 호출로 AMI 제어까지 됩니다.

### `src/asterisk/asterisk.controller.ts`

```ts
import { Body, Controller, Get, Post } from '@nestjs/common';
import { AmiCommandService } from './ami/ami.command.service';
import { OriginateCallDto } from './dto/originate-call.dto';
import { TransferCallDto } from './dto/transfer-call.dto';
import { HangupCallDto } from './dto/hangup-call.dto';
import { CallSessionRepository } from './services/call-session.repository';
import { QueueSummaryService } from './engine/queue-summary.service';

@Controller()
export class AsteriskController {
  private readonly tenantId =
    process.env.DEFAULT_TENANT_ID ?? '00000000-0000-0000-0000-000000000001';

  constructor(
    private readonly amiCommandService: AmiCommandService,
    private readonly callSessionRepository: CallSessionRepository,
    private readonly queueSummaryService: QueueSummaryService,
  ) {}

  @Post('calls/originate')
  originate(@Body() dto: OriginateCallDto) {
    const actionId = this.amiCommandService.originate(dto.extension, dto.targetNumber);
    return {
      success: true,
      data: { actionId },
      error: null,
    };
  }

  @Post('calls/transfer')
  transfer(@Body() dto: TransferCallDto) {
    const actionId =
      dto.transferType === 'blind'
        ? this.amiCommandService.blindTransfer(dto.channel, dto.target)
        : this.amiCommandService.attendedTransfer(dto.channel, dto.target);

    return {
      success: true,
      data: { actionId },
      error: null,
    };
  }

  @Post('calls/hangup')
  hangup(@Body() dto: HangupCallDto) {
    const actionId = this.amiCommandService.hangup(dto.channel);
    return {
      success: true,
      data: { actionId },
      error: null,
    };
  }

  @Get('calls/active')
  async activeCalls() {
    const items = await this.callSessionRepository.findActiveSessions(this.tenantId);
    return {
      success: true,
      data: items,
      error: null,
    };
  }

  @Get('queues/summary')
  getQueueSummary() {
    return {
      success: true,
      data: this.queueSummaryService.getAll(),
      error: null,
    };
  }
}
```

