# 1) Prisma schema 보강

기존 `schema.prisma`에 아래 모델과 enum/필드를 반영합니다.

```prisma
// prisma/schema.prisma

generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

enum UserRole {
  agent
  supervisor
  admin
}

enum AgentStatusCode {
  LOGGED_OUT
  AVAILABLE
  RINGING
  TALKING
  AFTER_CALL_WORK
  BREAK
  MEAL
  TRAINING
  SYSTEM_PAUSED
  MANUAL_PAUSED
}

enum CallDirection {
  inbound
  outbound
  internal
}

enum SessionStatus {
  NEW
  IVR
  QUEUED
  RINGING_AGENT
  TALKING
  HOLD
  TRANSFERRING
  AFTER_CALL_WORK
  ENDED
}

enum LegType {
  inbound
  agent
  outbound
  transfer
  ivr
  local
}

enum TransferType {
  blind
  attended
  queue
  external
}

enum TransferResult {
  requested
  ringing
  bridged
  completed
  cancelled
  failed
}

enum QueueEventType {
  JOIN
  LEAVE
  ABANDON
  TIMEOUT
  AGENT_CALLED
  AGENT_CONNECT
  AGENT_COMPLETE
}

model Agent {
  id                String               @id @default(uuid()) @db.Uuid
  tenantId          String               @db.Uuid
  loginId           String               @unique
  passwordHash      String
  agentCode         String               @unique
  agentName         String
  extension         String               @unique
  sipEndpoint       String?
  role              UserRole             @default(agent)
  employmentStatus  String               @default("active")
  defaultQueueId    String?              @db.Uuid
  lastLoginAt       DateTime?
  isActive          Boolean              @default(true)
  createdAt         DateTime             @default(now())
  updatedAt         DateTime             @updatedAt

  callSessions      CallSession[]        @relation("PrimaryAgentCallSessions")
  callLegs          CallLeg[]
  memos             CallMemo[]
