# 7) Transfer 추적 서비스

## `src/modules/calls/transfer-tracker.service.ts`

```ts
import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { TransferResult, TransferType } from '@prisma/client';

@Injectable()
export class TransferTrackerService {
  private readonly logger = new Logger(TransferTrackerService.name);

  constructor(private readonly prisma: PrismaService) {}

  async createRequested(params: {
    tenantId: string;
    callId: string;
    linkedid: string;
    transferType: TransferType;
    fromAgentId?: string | null;
    toAgentId?: string | null;
    fromExtension?: string | null;
    toExtension?: string | null;
    requestedAt?: Date;
  }) {
    return this.prisma.callTransfer.create({
      data: {
        tenantId: params.tenantId,
        callId: params.callId,
        linkedid: params.linkedid,
        transferType: params.transferType,
        fromAgentId: params.fromAgentId ?? null,
        toAgentId: params.toAgentId ?? null,
        fromExtension: params.fromExtension ?? null,
        toExtension: params.toExtension ?? null,
        transferResult: TransferResult.requested,
        requestedAt: params.requestedAt ?? new Date(),
      },
    });
  }

  async markRinging(transferId: string) {
    return this.prisma.callTransfer.update({
      where: { id: transferId },
      data: { transferResult: TransferResult.ringing },
    });
  }

  async markBridged(transferId: string) {
    return this.prisma.callTransfer.update({
      where: { id: transferId },
      data: { transferResult: TransferResult.bridged },
    });
  }

  async markCompleted(transferId: string) {
    return this.prisma.callTransfer.update({
      where: { id: transferId },
      data: {
        transferResult: TransferResult.completed,
        completedAt: new Date(),
      },
    });
  }

  async markFailedByLinkedid(linkedid: string) {
    const latest = await this.prisma.callTransfer.findFirst({
      where: {
        linkedid,
        transferResult: {
          in: [TransferResult.requested, TransferResult.ringing, TransferResult.bridged],
        },
      },
      orderBy: { requestedAt: 'desc' },
    });

    if (!latest) return null;

    return this.prisma.callTransfer.update({
      where: { id: latest.id },
      data: { transferResult: TransferResult.failed },
    });
  }

  async findLatestPendingByLinkedid(linkedid: string) {
    return this.prisma.callTransfer.findFirst({
      where: {
        linkedid,
        transferResult: {
          in: [TransferResult.requested, TransferResult.ringing, TransferResult.bridged],
        },
      },
      orderBy: { requestedAt: 'desc' },
    });
  }
}
