# 8) AMI Session Engine transfer 보강

핵심 포인트:
- **blind transfer**: 전환 요청 후 원 상담원 브리지 종료, 대상 leg 생성/브리지 완료 시 `completed`
- **attended transfer**: 제3자 호출 leg 생성 → 상담원 협의 브리지 → 최종 고객 브리지 재구성 시 `completed`
- linkedid 기준으로 동일 세션 묶음 유지 fileciteturn0file1

## `src/modules/ami/session-engine.service.ts`

```ts
import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import {
  AgentStatusCode,
  LegType,
  QueueEventType,
  SessionStatus,
  TransferType,
} from '@prisma/client';
import { AmiEvent } from './types/ami-event.type';
import { TransferTrackerService } from '../calls/transfer-tracker.service';

@Injectable()
export class SessionEngineService {
  private readonly logger = new Logger(SessionEngineService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly transferTracker: TransferTrackerService,
  ) {}

  private readonly tenantId = process.env.DEFAULT_TENANT_ID!;

  async handleEvent(event: AmiEvent): Promise<void> {
    const eventName = event.Event ?? '';
    const linkedid = event.Linkedid || event.DestLinkedid || event.Uniqueid;

    await this.saveRaw(eventName, linkedid, event.Uniqueid, event);

    if (!linkedid) return;

    switch (eventName) {
      case 'Newchannel':
        await this.handleNewchannel(linkedid, event);
        break;
      case 'Newstate':
        await this.handleNewstate(linkedid, event);
        break;
      case 'DialBegin':
        await this.handleDialBegin(linkedid, event);
        break;
      case 'DialEnd':
        await this.handleDialEnd(linkedid, event);
        break;
      case 'QueueCallerJoin':
        await this.handleQueueCallerJoin(linkedid, event);
        break;
      case 'QueueCallerLeave':
        await this.handleQueueCallerLeave(linkedid, event);
        break;
      case 'AgentCalled':
        await this.handleAgentCalled(linkedid, event);
        break;
      case 'AgentConnect':
        await this.handleAgentConnect(linkedid, event);
        break;
      case 'AgentComplete':
        await this.handleAgentComplete(linkedid, event);
        break;
      case 'BridgeEnter':
        await this.handleBridgeEnter(linkedid, event);
        break;
      case 'BridgeLeave':
        await this.handleBridgeLeave(linkedid, event);
        break;
      case 'BlindTransfer':
        await this.handleBlindTransfer(linkedid, event);
        break;
      case 'AttendedTransfer':
        await this.handleAttendedTransfer(linkedid, event);
        break;
      case 'Hangup':
        await this.handleHangup(linkedid, event);
        break;
      default:
        break;
    }
  }

  private async saveRaw(
    eventName: string,
    linkedid?: string,
    uniqueid?: string,
    payload?: Record<string, unknown>,
  ) {
    await this.prisma.rawAmiEvent.create({
      data: {
        tenantId: this.tenantId,
        linkedid: linkedid ?? null,
        uniqueid: uniqueid ?? null,
        eventName,
        eventTime: new Date(),
        payload: payload ?? {},
      },
    });
  }

  private async ensureCallSession(linkedid: string, event: AmiEvent) {
    let call = await this.prisma.callSession.findFirst({
      where: { tenantId: this.tenantId, linkedid },
    });

    if (call) return call;

    const ani = event.CallerIDNum ?? null;
    const dnis = event.Exten ?? null;

    call = await this.prisma.callSession.create({
      data: {
        tenantId: this.tenantId,
        linkedid,
        direction: 'inbound',
        ani,
        aniNormalized: ani?.replace(/\D/g, '') ?? null,
        dnis,
        didNumber: dnis,
        sessionStatus: SessionStatus.NEW,
        startedAt: new Date(),
      },
    });

    return call;
  }

  private resolveLegType(channel?: string): LegType {
    if (!channel) return LegType.local;
    if (channel.startsWith('Local/')) return LegType.local;
    if (channel.startsWith('PJSIP/') || channel.startsWith('SIP/')) return LegType.agent;
    return LegType.inbound;
  }

  private async upsertLeg(callId: string, linkedid: string, event: AmiEvent) {
    const uniqueid = event.Uniqueid;
    if (!uniqueid) return null;

    const existing = await this.prisma.callLeg.findFirst({
      where: { tenantId: this.tenantId, uniqueid },
    });

    if (existing) {
      return this.prisma.callLeg.update({
        where: { id: existing.id },
        data: {
          channelName: event.Channel ?? existing.channelName,
          stateCode: event.ChannelStateDesc ?? existing.stateCode,
        },
      });
    }

    return this.prisma.callLeg.create({
      data: {
        callId,
        tenantId: this.tenantId,
        linkedid,
        uniqueid,
        parentUniqueid: null,
        legType: this.resolveLegType(event.Channel),
        channelName: event.Channel ?? null,
        endpoint: this.extractExtension(event.Channel),
        stateCode: event.ChannelStateDesc ?? null,
        startedAt: new Date(),
      },
    });
  }

  private extractExtension(channel?: string): string | null {
    if (!channel) return null;
    const match = channel.match(/(?:PJSIP|SIP|Local)\/([^-/@]+)/);
    return match?.[1] ?? null;
  }

  private async findAgentByExtension(extension?: string | null) {
    if (!extension) return null;
    return this.prisma.agent.findFirst({
      where: {
        tenantId: this.tenantId,
        extension,
        isActive: true,
      },
    });
  }

  private async handleNewchannel(linkedid: string, event: AmiEvent) {
    const call = await this.ensureCallSession(linkedid, event);
    await this.upsertLeg(call.id, linkedid, event);
  }

  private async handleNewstate(linkedid: string, event: AmiEvent) {
    const call = await this.ensureCallSession(linkedid, event);

    if (event.ChannelStateDesc === 'Ringing') {
      await this.prisma.callSession.update({
        where: { id: call.id },
        data: {
          sessionStatus: SessionStatus.RINGING_AGENT,
          ringingAt: call.ringingAt ?? new Date(),
        },
      });
    }

    await this.upsertLeg(call.id, linkedid, event);
  }

  private async handleDialBegin(linkedid: string, event: AmiEvent) {
    const call = await this.ensureCallSession(linkedid, event);
    await this.upsertLeg(call.id, linkedid, event);

    const destExt = this.extractExtension(event.DestChannel);
    const destAgent = await this.findAgentByExtension(destExt);

    if (destAgent) {
      await this.prisma.callSession.update({
        where: { id: call.id },
        data: {
          sessionStatus: SessionStatus.RINGING_AGENT,
          primaryAgentId: call.primaryAgentId ?? destAgent.id,
          ringingAt: call.ringingAt ?? new Date(),
        },
      });
    }
  }

  private async handleDialEnd(linkedid: string, event: AmiEvent) {
    const call = await this.ensureCallSession(linkedid, event);

    if ((event.DialStatus ?? '').toUpperCase() === 'ANSWER') {
      await this.prisma.callSession.update({
        where: { id: call.id },
        data: {
          sessionStatus: SessionStatus.TALKING,
          answeredAt: call.answeredAt ?? new Date(),
        },
      });

      const pendingTransfer = await this.transferTracker.findLatestPendingByLinkedid(linkedid);
      if (pendingTransfer) {
        await this.transferTracker.markRinging(pendingTransfer.id);
      }
    }
  }

  private async handleQueueCallerJoin(linkedid: string, event: AmiEvent) {
    const call = await this.ensureCallSession(linkedid, event);
    const queue = await this.prisma.queue.findFirst({
      where: { tenantId: this.tenantId, queueName: event.Queue, isActive: true },
    });

    await this.prisma.callSession.update({
      where: { id: call.id },
      data: {
        queueId: queue?.id ?? null,
        queueName: event.Queue ?? null,
        queuedAt: call.queuedAt ?? new Date(),
        sessionStatus: SessionStatus.QUEUED,
      },
    });

    await this.prisma.queueEvent.create({
      data: {
        callId: call.id,
        tenantId: this.tenantId,
        linkedid,
        queueId: queue?.id ?? null,
        queueName: event.Queue ?? 'unknown',
        eventType: QueueEventType.JOIN,
        eventTime: new Date(),
        positionNo: event.Position ? Number(event.Position) : null,
        rawPayload: event as unknown as object,
      },
    });
  }

  private async handleQueueCallerLeave(linkedid: string, event: AmiEvent) {
    const call = await this.ensureCallSession(linkedid, event);

    await this.prisma.queueEvent.create({
      data: {
        callId: call.id,
        tenantId: this.tenantId,
        linkedid,
        queueId: call.queueId ?? null,
        queueName: call.queueName ?? 'unknown',
        eventType:
          (event.Reason ?? '').toUpperCase() === 'ABANDON'
            ? QueueEventType.ABANDON
            : QueueEventType.LEAVE,
        eventTime: new Date(),
        waitSeconds: call.queuedAt
          ? Math.max(0, Math.floor((Date.now() - call.queuedAt.getTime()) / 1000))
          : 0,
        positionNo: event.Position ? Number(event.Position) : null,
        rawPayload: event as unknown as object,
      },
    });

    if ((event.Reason ?? '').toUpperCase() === 'ABANDON') {
      await this.prisma.callSession.update({
        where: { id: call.id },
        data: {
          abandonFlag: true,
          resultCode: 'ABANDONED',
          sessionStatus: SessionStatus.ENDED,
          endedAt: new Date(),
          waitSeconds: call.queuedAt
            ? Math.max(0, Math.floor((Date.now() - call.queuedAt.getTime()) / 1000))
            : call.waitSeconds,
        },
      });
    }
  }

  private async handleAgentCalled(linkedid: string, event: AmiEvent) {
    const call = await this.ensureCallSession(linkedid, event);
    const ext = this.extractExtension(event.Interface) || this.extractExtension(event.MemberName);
    const agent = await this.findAgentByExtension(ext);

    await this.prisma.queueEvent.create({
      data: {
        callId: call.id,
        tenantId: this.tenantId,
        linkedid,
        queueId: call.queueId ?? null,
        queueName: call.queueName ?? 'unknown',
        agentId: agent?.id ?? null,
        eventType: QueueEventType.AGENT_CALLED,
        eventTime: new Date(),
        waitSeconds: event.HoldTime ? Number(event.HoldTime) : call.waitSeconds,
        positionNo: event.Position ? Number(event.Position) : null,
        rawPayload: event as unknown as object,
      },
    });

    await this.prisma.callSession.update({
      where: { id: call.id },
      data: {
        sessionStatus: SessionStatus.RINGING_AGENT,
        primaryAgentId: agent?.id ?? call.primaryAgentId,
        ringingAt: call.ringingAt ?? new Date(),
        waitSeconds: event.HoldTime ? Number(event.HoldTime) : call.waitSeconds,
      },
    });
  }

  private async handleAgentConnect(linkedid: string, event: AmiEvent) {
    const call = await this.ensureCallSession(linkedid, event);
    const ext = this.extractExtension(event.Interface) || this.extractExtension(event.MemberName);
    const agent = await this.findAgentByExtension(ext);

    await this.prisma.queueEvent.create({
      data: {
        callId: call.id,
        tenantId: this.tenantId,
        linkedid,
        queueId: call.queueId ?? null,
        queueName: call.queueName ?? 'unknown',
        agentId: agent?.id ?? null,
        eventType: QueueEventType.AGENT_CONNECT,
        eventTime: new Date(),
        waitSeconds: event.HoldTime ? Number(event.HoldTime) : call.waitSeconds,
        ringSeconds: event.RingTime ? Number(event.RingTime) : 0,
        rawPayload: event as unknown as object,
      },
    });

    await this.prisma.callSession.update({
      where: { id: call.id },
      data: {
        sessionStatus: SessionStatus.TALKING,
        primaryAgentId: agent?.id ?? call.primaryAgentId,
        answeredAt: call.answeredAt ?? new Date(),
        waitSeconds: event.HoldTime ? Number(event.HoldTime) : call.waitSeconds,
        ringSeconds: event.RingTime ? Number(event.RingTime) : call.ringSeconds,
      },
    });

    if (agent) {
      await this.setAgentStatus(agent.id, AgentStatusCode.TALKING);
    }
  }

  private async handleAgentComplete(linkedid: string, event: AmiEvent) {
    const call = await this.ensureCallSession(linkedid, event);
    const ext = this.extractExtension(event.Interface) || this.extractExtension(event.MemberName);
    const agent = await this.findAgentByExtension(ext);

    await this.prisma.queueEvent.create({
      data: {
        callId: call.id,
        tenantId: this.tenantId,
        linkedid,
        queueId: call.queueId ?? null,
        queueName: call.queueName ?? 'unknown',
        agentId: agent?.id ?? null,
        eventType: QueueEventType.AGENT_COMPLETE,
        eventTime: new Date(),
        waitSeconds: call.waitSeconds,
        ringSeconds: call.ringSeconds,
        rawPayload: event as unknown as object,
      },
    });

    await this.prisma.callSession.update({
      where: { id: call.id },
      data: {
        sessionStatus: SessionStatus.AFTER_CALL_WORK,
        acwSeconds: 0,
      },
    });

    if (agent) {
      await this.setAgentStatus(agent.id, AgentStatusCode.AFTER_CALL_WORK);
    }
  }

  private async handleBridgeEnter(linkedid: string, event: AmiEvent) {
    const call = await this.ensureCallSession(linkedid, event);

    await this.prisma.callSession.update({
      where: { id: call.id },
      data: {
        sessionStatus: SessionStatus.TALKING,
        answeredAt: call.answeredAt ?? new Date(),
      },
    });

    if (event.Uniqueid) {
      const leg = await this.prisma.callLeg.findFirst({
        where: { tenantId: this.tenantId, uniqueid: event.Uniqueid },
      });
      if (leg && !leg.bridgedAt) {
        await this.prisma.callLeg.update({
          where: { id: leg.id },
          data: {
            bridgedAt: new Date(),
            bridgedChannelName: event.DestChannel ?? null,
            stateCode: 'Up',
          },
        });
      }
    }

    const pendingTransfer = await this.transferTracker.findLatestPendingByLinkedid(linkedid);
    if (pendingTransfer) {
      await this.transferTracker.markBridged(pendingTransfer.id);
    }
  }

  private async handleBridgeLeave(linkedid: string, event: AmiEvent) {
    const call = await this.ensureCallSession(linkedid, event);
    if (call.sessionStatus === SessionStatus.TRANSFERRING) {
      return;
    }

    const holdSeconds = call.answeredAt
      ? Math.max(0, Math.floor((Date.now() - call.answeredAt.getTime()) / 1000))
      : call.holdSeconds;

    await this.prisma.callSession.update({
      where: { id: call.id },
      data: {
        holdSeconds,
        sessionStatus: SessionStatus.HOLD,
      },
    });
  }

  private async handleBlindTransfer(linkedid: string, event: AmiEvent) {
    const call = await this.ensureCallSession(linkedid, event);

    const fromExt = this.extractExtension(event.TransfererChannel);
    const toExt =
      this.extractExtension(event.TargetChannel) ||
      this.extractExtension(event.TransfereeChannel) ||
      event.Exten ||
      null;

    const fromAgent = await this.findAgentByExtension(fromExt);
    const toAgent = await this.findAgentByExtension(toExt);

    const transfer = await this.transferTracker.createRequested({
      tenantId: this.tenantId,
      callId: call.id,
      linkedid,
      transferType: TransferType.blind,
      fromAgentId: fromAgent?.id ?? null,
      toAgentId: toAgent?.id ?? null,
      fromExtension: fromExt,
      toExtension: toExt,
    });

    await this.prisma.callSession.update({
      where: { id: call.id },
      data: {
        transferFlag: true,
        sessionStatus: SessionStatus.TRANSFERRING,
      },
    });

    if (toAgent) {
      await this.transferTracker.markCompleted(transfer.id);
      await this.prisma.callSession.update({
        where: { id: call.id },
        data: {
          primaryAgentId: toAgent.id,
          sessionStatus: SessionStatus.TALKING,
        },
      });
    }
  }

  private async handleAttendedTransfer(linkedid: string, event: AmiEvent) {
    const call = await this.ensureCallSession(linkedid, event);

    const fromExt = this.extractExtension(event.TransfererChannel);
    const toExt =
      this.extractExtension(event.TargetChannel) ||
      this.extractExtension(event.TransfereeChannel) ||
      event.Exten ||
      null;

    const fromAgent = await this.findAgentByExtension(fromExt);
    const toAgent = await this.findAgentByExtension(toExt);

    const transfer = await this.transferTracker.createRequested({
      tenantId: this.tenantId,
      callId: call.id,
      linkedid,
      transferType: TransferType.attended,
      fromAgentId: fromAgent?.id ?? null,
      toAgentId: toAgent?.id ?? null,
      fromExtension: fromExt,
      toExtension: toExt,
    });

    await this.prisma.callSession.update({
      where: { id: call.id },
      data: {
        transferFlag: true,
        sessionStatus: SessionStatus.TRANSFERRING,
      },
    });

    // attended transfer는 상담 협의 구간이 있으므로 일단 bridged로만 승격
    await this.transferTracker.markBridged(transfer.id);

    if (toAgent) {
      await this.prisma.callSession.update({
        where: { id: call.id },
        data: {
          primaryAgentId: toAgent.id,
        },
      });
    }
  }

  private async handleHangup(linkedid: string, event: AmiEvent) {
    const call = await this.ensureCallSession(linkedid, event);

    if (event.Uniqueid) {
      const leg = await this.prisma.callLeg.findFirst({
        where: { tenantId: this.tenantId, uniqueid: event.Uniqueid },
      });

      if (leg && !leg.endedAt) {
        const endedAt = new Date();
        await this.prisma.callLeg.update({
          where: { id: leg.id },
          data: {
            endedAt,
            durationSeconds: Math.max(
              0,
              Math.floor((endedAt.getTime() - leg.startedAt.getTime()) / 1000),
            ),
            disposition: 'HANGUP',
          },
        });
      }
    }

    const talkSeconds =
      call.answeredAt && !call.endedAt
        ? Math.max(0, Math.floor((Date.now() - call.answeredAt.getTime()) / 1000))
        : call.talkSeconds;

    await this.prisma.callSession.update({
      where: { id: call.id },
      data: {
        sessionStatus: SessionStatus.ENDED,
        endedAt: call.endedAt ?? new Date(),
        talkSeconds,
      },
    });

    const pendingTransfer = await this.transferTracker.findLatestPendingByLinkedid(linkedid);
    if (pendingTransfer) {
      await this.transferTracker.markCompleted(pendingTransfer.id);
    }

    if (call.primaryAgentId) {
      await this.setAgentStatus(call.primaryAgentId, AgentStatusCode.AFTER_CALL_WORK);
    }
  }

  private async setAgentStatus(agentId: string, statusCode: AgentStatusCode) {
    const current = await this.prisma.agentStatusHistory.findFirst({
      where: { tenantId: this.tenantId, agentId, endedAt: null },
      orderBy: { startedAt: 'desc' },
    });

    const now = new Date();

    if (current) {
      await this.prisma.agentStatusHistory.update({
        where: { id: current.id },
        data: {
          endedAt: now,
          durationSeconds: Math.max(
            0,
            Math.floor((now.getTime() - current.startedAt.getTime()) / 1000),
          ),
        },
      });
    }

    await this.prisma.agentStatusHistory.create({
      data: {
        tenantId: this.tenantId,
        agentId,
        statusCode,
        sourceType: 'system',
        startedAt: now,
      },
    });
  }
}
