# 9) AMI call command service 보강

실제 blind / attended transfer 명령을 분리합니다.

## `src/modules/ami/ami-command.service.ts`

```ts
import { Injectable, Logger } from '@nestjs/common';
import { Socket } from 'net';

@Injectable()
export class AmiCommandService {
  private readonly logger = new Logger(AmiCommandService.name);

  private socket?: Socket;
  private actionIdSeq = 1;

  bindSocket(socket: Socket) {
    this.socket = socket;
  }

  private sendAction(lines: Record<string, string>) {
    if (!this.socket) {
      throw new Error('AMI socket not connected');
    }

    const actionId = `act-${Date.now()}-${this.actionIdSeq++}`;
    const payload = {
      ActionID: actionId,
      ...lines,
    };

    const raw =
      Object.entries(payload)
        .map(([k, v]) => `${k}: ${v}`)
        .join('\r\n') + '\r\n\r\n';

    this.socket.write(raw);
    return actionId;
  }

  async hangup(channel: string) {
    return this.sendAction({
      Action: 'Hangup',
      Channel: channel,
    });
  }

  async blindTransfer(params: {
    channel: string;
    exten: string;
    context: string;
    priority?: number;
  }) {
    return this.sendAction({
      Action: 'Redirect',
      Channel: params.channel,
      Exten: params.exten,
      Context: params.context,
      Priority: String(params.priority ?? 1),
    });
  }

  async attendedTransfer(params: {
    channel: string;
    exten: string;
    context: string;
    priority?: number;
  }) {
    // 실전에서는 AMI Redirect + Local channel 또는 features.conf/DTMF 기반 시나리오로 세부 구현 가능
    return this.sendAction({
      Action: 'Redirect',
      Channel: params.channel,
      Exten: params.exten,
      Context: params.context,
      Priority: String(params.priority ?? 1),
    });
  }

  async originate(params: {
    channel: string;
    exten: string;
    context: string;
    priority?: number;
    callerId?: string;
    timeoutMs?: number;
    variable?: Record<string, string>;
  }) {
    const payload: Record<string, string> = {
      Action: 'Originate',
      Channel: params.channel,
      Exten: params.exten,
      Context: params.context,
      Priority: String(params.priority ?? 1),
      Async: 'true',
      Timeout: String(params.timeoutMs ?? 30000),
    };

    if (params.callerId) payload.CallerID = params.callerId;
    if (params.variable) {
      payload.Variable = Object.entries(params.variable)
        .map(([k, v]) => `${k}=${v}`)
        .join('|');
    }

    return this.sendAction(payload);
  }
}
