# 10) CallsService 전환 API 구현

## `src/modules/calls/calls.service.ts`

```ts
import {
  BadRequestException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { AmiCommandService } from '../ami/ami-command.service';
import { TransferCallDto, TransferTargetTypeDto, TransferTypeDto } from './dto/transfer-call.dto';
import { TransferType } from '@prisma/client';

@Injectable()
export class CallsService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly amiCommandService: AmiCommandService,
  ) {}

  async getCallDetail(callId: string) {
    const call = await this.prisma.callSession.findUnique({
      where: { id: callId },
      include: {
        legs: { orderBy: { startedAt: 'asc' } },
        transfers: { orderBy: { requestedAt: 'asc' } },
      },
    });

    if (!call) {
      throw new NotFoundException('Call not found');
    }

    return {
      callId: call.id,
      linkedid: call.linkedid,
      direction: call.direction,
      ani: call.ani,
      dnis: call.dnis,
      queueName: call.queueName,
      sessionStatus: call.sessionStatus,
      transferFlag: call.transferFlag,
      waitSeconds: call.waitSeconds,
      talkSeconds: call.talkSeconds,
      holdSeconds: call.holdSeconds,
      legs: call.legs.map((leg) => ({
        legId: leg.id,
        uniqueid: leg.uniqueid,
        legType: leg.legType,
        channelName: leg.channelName,
        stateCode: leg.stateCode,
        dialStatus: leg.dialStatus,
        startedAt: leg.startedAt,
        bridgedAt: leg.bridgedAt,
        endedAt: leg.endedAt,
        durationSeconds: leg.durationSeconds,
      })),
      transfers: call.transfers.map((t) => ({
        transferId: t.id,
        transferType: t.transferType,
        fromAgentId: t.fromAgentId,
        toAgentId: t.toAgentId,
        fromExtension: t.fromExtension,
        toExtension: t.toExtension,
        transferResult: t.transferResult,
        requestedAt: t.requestedAt,
        completedAt: t.completedAt,
      })),
    };
  }

  async transferCall(callId: string, dto: TransferCallDto, actorAgentId?: string) {
    const call = await this.prisma.callSession.findUnique({
      where: { id: callId },
      include: {
        legs: {
          where: { endedAt: null },
          orderBy: { startedAt: 'desc' },
        },
        primaryAgent: true,
      },
    });

    if (!call) {
      throw new NotFoundException('Call not found');
    }

    if (!call.legs.length) {
      throw new BadRequestException('No active channel found');
    }

    const activeAgentLeg =
      call.legs.find((leg) => leg.legType === 'agent' && !!leg.channelName) ??
      call.legs.find((leg) => !!leg.channelName);

    if (!activeAgentLeg?.channelName) {
      throw new BadRequestException('Transferable channel not found');
    }

    if (
      dto.targetType === TransferTargetTypeDto.QUEUE &&
      dto.transferType !== TransferTypeDto.BLIND
    ) {
      throw new BadRequestException('Queue transfer only supports blind transfer');
    }

    if (dto.targetType === TransferTargetTypeDto.PHONE && dto.transferType === TransferTypeDto.ATTENDED) {
      throw new BadRequestException('Attended transfer to external phone is not enabled in this version');
    }

    const targetContext =
      dto.targetType === TransferTargetTypeDto.QUEUE
        ? 'queue-entry-api'
        : dto.targetType === TransferTargetTypeDto.PHONE
        ? 'outbound-transfer'
        : 'from-internal-transfer';

    if (dto.transferType === TransferTypeDto.BLIND) {
      await this.prisma.callTransfer.create({
        data: {
          tenantId: call.tenantId,
          callId: call.id,
          linkedid: call.linkedid,
          transferType: TransferType.blind,
          fromAgentId: actorAgentId ?? call.primaryAgentId ?? null,
          fromExtension: call.primaryAgent?.extension ?? null,
          toExtension: dto.target,
          transferResult: 'requested',
          requestedAt: new Date(),
        },
      });

      await this.prisma.callSession.update({
        where: { id: call.id },
        data: {
          transferFlag: true,
          sessionStatus: 'TRANSFERRING',
        },
      });

      await this.amiCommandService.blindTransfer({
        channel: activeAgentLeg.channelName,
        exten: dto.target,
        context: targetContext,
        priority: 1,
      });

      return { accepted: true };
    }

    await this.prisma.callTransfer.create({
      data: {
        tenantId: call.tenantId,
        callId: call.id,
        linkedid: call.linkedid,
        transferType: TransferType.attended,
        fromAgentId: actorAgentId ?? call.primaryAgentId ?? null,
        fromExtension: call.primaryAgent?.extension ?? null,
        toExtension: dto.target,
        transferResult: 'requested',
        requestedAt: new Date(),
      },
    });

    await this.prisma.callSession.update({
      where: { id: call.id },
      data: {
        transferFlag: true,
        sessionStatus: 'TRANSFERRING',
      },
    });

    await this.amiCommandService.attendedTransfer({
      channel: activeAgentLeg.channelName,
      exten: dto.target,
      context: targetContext,
      priority: 1,
    });

    return { accepted: true };
  }
}
