# 12) Queue summary 집계 서비스 고도화

핵심 포인트:
- 단순 waiting count가 아니라
  - waiting / ringing / talking
  - available agents / logged-in agents
  - avg wait / avg talk / avg acw
  - answer rate / abandon rate / SLA
  - active call list
까지 계산합니다.
- 설계서의 `queue summary`, `실시간 상태판`, `queue.summary.updated` 요구를 직접 반영합니다. fileciteturn0file1 fileciteturn0file2

## `src/modules/queues/queues.service.ts`

```ts
import { Injectable } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { AgentStatusCode, QueueEventType, SessionStatus } from '@prisma/client';

@Injectable()
export class QueuesService {
  private readonly tenantId = process.env.DEFAULT_TENANT_ID!;

  constructor(private readonly prisma: PrismaService) {}

  async getSummary() {
    const queues = await this.prisma.queue.findMany({
      where: {
        tenantId: this.tenantId,
        isActive: true,
      },
      include: {
        memberships: {
          where: { isActive: true },
          include: { agent: true },
        },
      },
      orderBy: { queueName: 'asc' },
    });

    const now = new Date();
    const windowStart = new Date(now.getTime() - 24 * 60 * 60 * 1000);

    const result = await Promise.all(
      queues.map(async (queue) => {
        const activeCalls = await this.prisma.callSession.findMany({
          where: {
            tenantId: this.tenantId,
            queueId: queue.id,
            sessionStatus: {
              in: [
                SessionStatus.QUEUED,
                SessionStatus.RINGING_AGENT,
                SessionStatus.TALKING,
                SessionStatus.TRANSFERRING,
                SessionStatus.HOLD,
                SessionStatus.AFTER_CALL_WORK,
              ],
            },
            endedAt: null,
          },
          orderBy: { startedAt: 'asc' },
        });

        const waitingCalls = activeCalls.filter((c) => c.sessionStatus === SessionStatus.QUEUED);
        const ringingCalls = activeCalls.filter((c) => c.sessionStatus === SessionStatus.RINGING_AGENT);
        const talkingCalls = activeCalls.filter((c) =>
          [SessionStatus.TALKING, SessionStatus.TRANSFERRING, SessionStatus.HOLD].includes(c.sessionStatus),
        );

        const latestStatuses = await Promise.all(
          queue.memberships.map(async (m) => {
            const latest = await this.prisma.agentStatusHistory.findFirst({
              where: {
                tenantId: this.tenantId,
                agentId: m.agentId,
              },
              orderBy: { startedAt: 'desc' },
            });

            const activeTalkingCalls = await this.prisma.callSession.count({
              where: {
                tenantId: this.tenantId,
                primaryAgentId: m.agentId,
                sessionStatus: {
                  in: [SessionStatus.TALKING, SessionStatus.TRANSFERRING, SessionStatus.HOLD],
                },
                endedAt: null,
              },
            });

            const statusCode = latest?.statusCode ?? AgentStatusCode.LOGGED_OUT;
            const isAvailable = statusCode === AgentStatusCode.AVAILABLE;
            const isTalking = statusCode === AgentStatusCode.TALKING;

            return {
              agentId: m.agent.id,
              extension: m.agent.extension,
              agentName: m.agent.agentName,
              statusCode,
              isAvailable,
              isTalking,
              activeTalkingCalls,
            };
          }),
        );

        const completedCalls = await this.prisma.callSession.findMany({
          where: {
            tenantId: this.tenantId,
            queueId: queue.id,
            startedAt: { gte: windowStart },
          },
          select: {
            waitSeconds: true,
            talkSeconds: true,
            acwSeconds: true,
            abandonFlag: true,
            answeredAt: true,
          },
        });

        const totalCount = completedCalls.length;
        const answeredCount = completedCalls.filter((c) => !!c.answeredAt && !c.abandonFlag).length;
        const abandonedCount = completedCalls.filter((c) => c.abandonFlag).length;
        const slaCount = completedCalls.filter(
          (c) => !!c.answeredAt && !c.abandonFlag && c.waitSeconds <= 20,
        ).length;

        const avgWaitSeconds = totalCount
          ? round2(
              completedCalls.reduce((sum, c) => sum + (c.waitSeconds ?? 0), 0) / totalCount,
            )
          : 0;

        const avgTalkSeconds = answeredCount
          ? round2(
              completedCalls
                .filter((c) => !!c.answeredAt && !c.abandonFlag)
                .reduce((sum, c) => sum + (c.talkSeconds ?? 0), 0) / answeredCount,
            )
          : 0;

        const avgAcwSeconds = answeredCount
          ? round2(
              completedCalls
                .filter((c) => !!c.answeredAt && !c.abandonFlag)
                .reduce((sum, c) => sum + (c.acwSeconds ?? 0), 0) / answeredCount,
            )
          : 0;

        const answerRatePct = totalCount ? round2((answeredCount / totalCount) * 100) : 0;
        const abandonRatePct = totalCount ? round2((abandonedCount / totalCount) * 100) : 0;
        const slaAnswerRatePct = totalCount ? round2((slaCount / totalCount) * 100) : 0;

        const longestWaitingSeconds = waitingCalls.length
          ? Math.max(
              ...waitingCalls.map((c) =>
                c.queuedAt
                  ? Math.max(0, Math.floor((Date.now() - c.queuedAt.getTime()) / 1000))
                  : c.waitSeconds,
              ),
            )
          : 0;

        const latestPositions = await this.prisma.queueEvent.findMany({
          where: {
            tenantId: this.tenantId,
            queueId: queue.id,
            linkedid: { in: activeCalls.map((c) => c.linkedid) },
          },
          orderBy: { eventTime: 'desc' },
          distinct: ['linkedid'],
        });

        return {
          queueId: queue.id,
          queueName: queue.queueName,
          queueDisplayName: queue.queueDisplayName,
          counters: {
            waitingCount: waitingCalls.length,
            ringingCount: ringingCalls.length,
            talkingCount: talkingCalls.length,
            availableAgentCount: latestStatuses.filter((s) => s.isAvailable).length,
            loggedInAgentCount: latestStatuses.filter(
              (s) => s.statusCode !== AgentStatusCode.LOGGED_OUT,
            ).length,
          },
          metrics: {
            avgWaitSeconds,
            avgTalkSeconds,
            avgAcwSeconds,
            longestWaitingSeconds,
            answerRatePct,
            abandonRatePct,
            slaAnswerRatePct,
          },
          agents: latestStatuses,
          activeCalls: activeCalls.map((call) => ({
            callId: call.id,
            linkedid: call.linkedid,
            ani: call.ani,
            queueName: call.queueName,
            sessionStatus: call.sessionStatus,
            startedAt: call.startedAt,
            queuedAt: call.queuedAt,
            waitSeconds: call.queuedAt
              ? Math.max(0, Math.floor((Date.now() - call.queuedAt.getTime()) / 1000))
              : call.waitSeconds,
            positionNo:
              latestPositions.find((p) => p.linkedid === call.linkedid)?.positionNo ?? null,
          })),
        };
      }),
    );

    return result;
  }
}

function round2(value: number): number {
  return Math.round(value * 100) / 100;
}
```

