```ts
import {
  OnGatewayConnection,
  OnGatewayInit,
  WebSocketGateway,
  WebSocketServer,
} from '@nestjs/websockets';
import { Server, Socket } from 'socket.io';

@WebSocketGateway({
  namespace: '/ws/admin',
  cors: { origin: '*' },
})
export class RealtimeGateway implements OnGatewayInit, OnGatewayConnection {
  @WebSocketServer()
  server!: Server;

  afterInit() {}

  handleConnection(_client: Socket) {}

  emitCallCreated(payload: unknown) {
    this.server.emit('call.created', payload);
  }

  emitCallUpdated(payload: unknown) {
    this.server.emit('call.updated', payload);
  }

  emitCallEnded(payload: unknown) {
    this.server.emit('call.ended', payload);
  }

  emitQueueSummaryUpdated(payload: unknown) {
    this.server.emit('queue.summary.updated', payload);
  }

  emitAgentStatusChanged(payload: unknown) {
    this.server.emit('agent.status.changed', payload);
  }
}
