import { applyDecorators, Type } from '@nestjs/common';
import { ApiExtraModels, ApiOkResponse, getSchemaPath } from '@nestjs/swagger';
import { CommonResponseDto } from '../dto/common-response.dto';

export function ApiWrappedOkResponse<TModel extends Type<unknown>>(model: TModel, description?: string) {
  return applyDecorators(
    ApiExtraModels(CommonResponseDto, model),
    ApiOkResponse({
      description,
      schema: {
        allOf: [
          { $ref: getSchemaPath(CommonResponseDto) },
          {
            properties: {
              success: { example: true },
              data: { $ref: getSchemaPath(model) },
              error: { example: null, nullable: true },
            },
          },
        ],
      },
    }),
  );
}

export function ApiWrappedOkArrayResponse<TModel extends Type<unknown>>(model: TModel, description?: string) {
  return applyDecorators(
    ApiExtraModels(CommonResponseDto, model),
    ApiOkResponse({
      description,
      schema: {
        allOf: [
          { $ref: getSchemaPath(CommonResponseDto) },
          {
            properties: {
              success: { example: true },
              data: {
                type: 'array',
                items: { $ref: getSchemaPath(model) },
              },
              error: { example: null, nullable: true },
            },
          },
        ],
      },
    }),
  );
}
