import { Injectable, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { ChangeAgentStatusRequestDto } from './dto/change-agent-status.request.dto';

@Injectable()
export class AgentsService {
  constructor(private readonly prisma: PrismaService) {}

  async changeStatus(agentId: string, dto: ChangeAgentStatusRequestDto, actor: any) {
    const agent = await this.prisma.agent.findUnique({
      where: { agentId },
    });

    if (!agent) throw new NotFoundException('Agent not found');

    await this.prisma.agentStatusHistory.create({
      data: {
        tenantId: agent.tenantId,
        agentId,
        statusCode: dto.statusCode,
        reasonCode: dto.reasonCode,
        reasonText: dto.reasonText,
        sourceType: actor.role === 'admin' ? 'admin' : 'agent',
        startedAt: new Date(),
      },
    });

    return {
      agentId,
      statusCode: dto.statusCode,
      changedAt: new Date(),
    };
  }
}
