```ts
import { Injectable, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { SaveCallMemoRequestDto } from './dto/save-call-memo.request.dto';
import { OriginateCallRequestDto } from './dto/originate-call.request.dto';
import { TransferCallRequestDto } from './dto/transfer-call.request.dto';
import { HangupCallRequestDto } from './dto/hangup-call.request.dto';
import { AmiTcpClient } from '../ami/ami-tcp.client';

@Injectable()
export class CallsService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly amiClient: AmiTcpClient,
  ) {}

  async getActiveCalls(user: any) {
    return this.prisma.callSession.findMany({
      where: {
        tenantId: user.tenantId,
        sessionStatus: {
          in: ['NEW', 'IVR', 'QUEUED', 'RINGING_AGENT', 'TALKING', 'HOLD', 'TRANSFERRING', 'AFTER_CALL_WORK'],
        },
      },
      orderBy: { startedAt: 'desc' },
    });
  }

  async getCallDetail(callId: string, user: any) {
    const call = await this.prisma.callSession.findFirst({
      where: { callId, tenantId: user.tenantId },
      include: {
        callLegs: true,
        queueEvents: true,
        callMemos: true,
        callTransfers: true,
        callRecordings: true,
      },
    });

    if (!call) throw new NotFoundException('Call not found');
    return call;
  }

  async saveMemo(callId: string, user: any, dto: SaveCallMemoRequestDto) {
    const call = await this.prisma.callSession.findFirst({
      where: { callId, tenantId: user.tenantId },
    });
    if (!call) throw new NotFoundException('Call not found');

    return this.prisma.callMemo.create({
      data: {
        callId,
        tenantId: user.tenantId,
        agentId: user.agentId,
        customerId: call.customerId,
        memoType: 'acw',
        resultCode: dto.resultCode,
        subResultCode: dto.subResultCode,
        memoText: dto.memoText,
        isFinal: dto.isFinal ?? true,
      },
    });
  }

  async originate(user: any, dto: OriginateCallRequestDto) {
    const actionId = `originate-${Date.now()}`;

    await this.amiClient.sendAction({
      Action: 'Originate',
      ActionID: actionId,
      Channel: `PJSIP/${dto.extension}`,
      Context: 'from-internal',
      Exten: dto.phoneNumber,
      Priority: '1',
      Async: 'true',
      Variable: `__TENANT_ID=${user.tenantId},__AGENT_ID=${user.agentId},__ORIGINATE_SOURCE=clicktocall`,
    });

    return {
      actionId,
      status: 'queued',
      extension: dto.extension,
      phoneNumber: dto.phoneNumber,
    };
  }

  async transfer(callId: string, user: any, dto: TransferCallRequestDto) {
    const call = await this.prisma.callSession.findFirst({
      where: { callId, tenantId: user.tenantId },
    });
    if (!call) throw new NotFoundException('Call not found');

    await this.prisma.callTransfer.create({
      data: {
        callId,
        tenantId: user.tenantId,
        linkedid: call.linkedid,
        transferType: dto.transferType,
        fromAgentId: user.agentId,
        toExtension: dto.target,
        requestedAt: new Date(),
      },
    });

    return {
      callId,
      transferType: dto.transferType,
      targetType: dto.targetType,
      target: dto.target,
      status: 'requested',
    };
  }

  async hangup(callId: string, user: any, dto: HangupCallRequestDto) {
    const call = await this.prisma.callSession.findFirst({
      where: { callId, tenantId: user.tenantId },
      include: { callLegs: true },
    });
    if (!call) throw new NotFoundException('Call not found');

    const activeLeg = call.callLegs.find((leg) => !leg.endedAt);
    if (activeLeg?.channelName) {
      await this.amiClient.sendAction({
        Action: 'Hangup',
        Channel: activeLeg.channelName,
      });
    }

    return {
      callId,
      requestedBy: user.agentId,
      reason: dto.reason ?? null,
      status: 'requested',
    };
  }
}
```

