@Injectable()
export class CustomersService {
  constructor(private readonly prisma: PrismaService) {}

  normalizePhone(phone: string) {
    return phone.replace(/\D/g, '');
  }

  async searchByPhone(user: any, phone: string) {
    const normalized = this.normalizePhone(phone);

    const rows = await this.prisma.customerPhone.findMany({
      where: {
        normalizedPhone: normalized,
        customer: {
          tenantId: user.tenantId,
        },
      },
      include: {
        customer: true,
      },
    });

    return Promise.all(
      rows.map(async (row) => {
        const recentCalls = await this.prisma.callSession.count({
          where: {
            tenantId: user.tenantId,
            customerId: row.customerId,
          },
        });

        return {
          customerId: row.customer.customerId,
          customerName: row.customer.customerName,
          grade: row.customer.grade,
          phones: [
            {
              phoneNumber: row.phoneNumber,
              isPrimary: row.isPrimary,
            },
          ],
          recentCalls,
        };
      }),
    );
  }
}
