import {
  ConnectedSocket,
  MessageBody,
  OnGatewayConnection,
  OnGatewayInit,
  SubscribeMessage,
  WebSocketGateway,
  WebSocketServer,
} from '@nestjs/websockets';
import { Logger } from '@nestjs/common';
import { Server, Socket } from 'socket.io';
import { RealtimeEventName } from './realtime.types';

@WebSocketGateway({
  namespace: '/ws',
  cors: { origin: '*' },
})
export class RealtimeGateway implements OnGatewayInit, OnGatewayConnection {
  @WebSocketServer()
  server!: Server;

  private readonly logger = new Logger(RealtimeGateway.name);

  afterInit() {
    this.logger.log('Realtime gateway initialized');
  }

  handleConnection(client: Socket) {
    this.logger.log(`WS connected: ${client.id}`);
  }

  @SubscribeMessage('subscribe.agent')
  handleSubscribeAgent(
    @ConnectedSocket() client: Socket,
    @MessageBody() payload: { tenantId: string; agentId: string },
  ) {
    client.join(`tenant:${payload.tenantId}`);
    client.join(`agent:${payload.agentId}`);
    return { subscribed: true };
  }

  emitToTenant(tenantId: string, event: RealtimeEventName, payload: unknown) {
    this.server.to(`tenant:${tenantId}`).emit(event, payload);
  }

  emitToAgent(agentId: string, event: RealtimeEventName, payload: unknown) {
    this.server.to(`agent:${agentId}`).emit(event, payload);
  }
}
