## src/ami/ami.parser.ts

```ts
import { Injectable } from '@nestjs/common';
import { AmiEventPacket } from './ami-event.types';

@Injectable()
export class AmiParser {
  private buffer = '';

  push(chunk: Buffer): AmiEventPacket[] {
    this.buffer += chunk.toString('utf8');
    const packets: AmiEventPacket[] = [];

    while (true) {
      const idx = this.buffer.indexOf('\r\n\r\n');
      if (idx < 0) break;

      const rawPacket = this.buffer.slice(0, idx);
      this.buffer = this.buffer.slice(idx + 4);

      const lines = rawPacket.split('\r\n');
      const packet: AmiEventPacket = {};

      for (const line of lines) {
        const sep = line.indexOf(':');
        if (sep > -1) {
          const key = line.slice(0, sep).trim();
          const value = line.slice(sep + 1).trim();
          packet[key] = value;
        }
      }

      if (Object.keys(packet).length > 0) {
        packets.push(packet);
      }
    }

    return packets;
  }
}
