## src/ami/ami-tcp.client.ts

```ts
import { Injectable, Logger, OnModuleInit } from '@nestjs/common';
import * as net from 'net';
import { AmiAction, AmiEventPacket } from './ami-event.types';
import { AmiParser } from './ami.parser';
import { AmiSessionEngine } from './ami-session.engine';

@Injectable()
export class AmiTcpClient implements OnModuleInit {
  private readonly logger = new Logger(AmiTcpClient.name);
  private socket: net.Socket | null = null;
  private connected = false;
  private reconnectTimer: NodeJS.Timeout | null = null;

  constructor(
    private readonly parser: AmiParser,
    private readonly sessionEngine: AmiSessionEngine,
  ) {}

  onModuleInit() {
    if ((process.env.AMI_ENABLED ?? 'true') === 'true') {
      this.connect();
    }
  }

  private connect() {
    const host = process.env.AMI_HOST ?? '127.0.0.1';
    const port = Number(process.env.AMI_PORT ?? 5038);

    this.socket = net.createConnection({ host, port }, () => {
      this.logger.log(`AMI connected ${host}:${port}`);
      this.connected = true;
      this.login();
    });

    this.socket.on('data', async (chunk: Buffer) => {
      const packets = this.parser.push(chunk);
      for (const packet of packets) {
        await this.handlePacket(packet);
      }
    });

    this.socket.on('error', (err) => {
      this.logger.error(`AMI socket error: ${err.message}`);
    });

    this.socket.on('close', () => {
      this.logger.warn('AMI socket closed');
      this.connected = false;
      this.scheduleReconnect();
    });
  }

  private login() {
    this.sendRaw({
      Action: 'Login',
      Username: process.env.AMI_USERNAME ?? '',
      Secret: process.env.AMI_SECRET ?? '',
      Events: 'on',
    });
  }

  private scheduleReconnect() {
    if (this.reconnectTimer) return;

    const delay = Number(process.env.AMI_RECONNECT_DELAY_MS ?? 5000);
    this.reconnectTimer = setTimeout(() => {
      this.reconnectTimer = null;
      this.connect();
    }, delay);
  }

  private async handlePacket(packet: AmiEventPacket) {
    if (packet.Event) {
      await this.sessionEngine.handleEvent(packet);
    }
  }

  private sendRaw(action: AmiAction) {
    if (!this.socket || !this.connected) return;

    const body =
      Object.entries(action)
        .map(([k, v]) => `${k}: ${v}`)
        .join('\r\n') + '\r\n\r\n';

    this.socket.write(body);
  }

  async sendAction(action: AmiAction) {
    this.sendRaw(action);
  }
}
