## src/ami/ami-session.engine.ts

```ts
import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { RealtimeGateway } from '../realtime/realtime.gateway';
import { AmiEventPacket } from './ami-event.types';

@Injectable()
export class AmiSessionEngine {
  private readonly logger = new Logger(AmiSessionEngine.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly realtimeGateway: RealtimeGateway,
  ) {}

  async handleEvent(packet: AmiEventPacket) {
    const eventName = packet.Event;
    const linkedid = packet.Linkedid || packet.LinkedID || packet.Uniqueid || packet.UniqueID;
    const uniqueid = packet.Uniqueid || packet.UniqueID || null;

    const tenantId = await this.resolveTenantId(packet);

    await this.prisma.rawAmiEvent.create({
      data: {
        tenantId,
        linkedid: linkedid ?? null,
        uniqueid,
        eventName,
        eventTime: new Date(),
        payload: packet as any,
      },
    });

    switch (eventName) {
      case 'Newchannel':
        await this.onNewChannel(packet, tenantId, linkedid, uniqueid);
        break;
      case 'QueueCallerJoin':
        await this.onQueueJoin(packet, tenantId, linkedid);
        break;
      case 'AgentCalled':
        await this.onAgentCalled(packet, tenantId, linkedid);
        break;
      case 'AgentConnect':
      case 'BridgeEnter':
        await this.onTalking(packet, tenantId, linkedid);
        break;
      case 'Hangup':
        await this.onHangup(packet, tenantId, linkedid, uniqueid);
        break;
      case 'AgentComplete':
        await this.onAgentComplete(packet, tenantId, linkedid);
        break;
      default:
        break;
    }
  }

  private async resolveTenantId(_packet: AmiEventPacket): Promise<string> {
    const tenant = await this.prisma.tenant.findFirst({
      where: { tenantCode: 'main' },
    });
    if (!tenant) {
      throw new Error('Default tenant(main) not found');
    }
    return tenant.tenantId;
  }

  private normalizePhone(value?: string | null) {
    if (!value) return null;
    return value.replace(/\D/g, '');
  }

  private async ensureSession(tenantId: string, linkedid: string, packet: AmiEventPacket) {
    let session = await this.prisma.callSession.findFirst({
      where: { tenantId, linkedid },
    });

    if (!session) {
      const caller = this.normalizePhone(packet.CallerIDNum || packet.CallerID || '');
      session = await this.prisma.callSession.create({
        data: {
          tenantId,
          linkedid,
          direction: 'inbound',
          ani: caller,
          aniNormalized: caller,
          dnis: packet.Exten ?? null,
          didNumber: packet.Exten ?? null,
          trunkName: packet.Channel ?? null,
          sessionStatus: 'NEW',
          startedAt: new Date(),
        },
      });

      this.realtimeGateway.emitToTenant(tenantId, 'call.created', {
        callId: session.callId,
        linkedid: session.linkedid,
        ani: session.ani,
        queueName: session.queueName,
        sessionStatus: session.sessionStatus,
      });
    }

    return session;
  }

  private async onNewChannel(packet: AmiEventPacket, tenantId: string, linkedid: string, uniqueid: string | null) {
    if (!linkedid || !uniqueid) return;

    const session = await this.ensureSession(tenantId, linkedid, packet);

    await this.prisma.callLeg.upsert({
      where: {
        tenantId_uniqueid: {
          tenantId,
          uniqueid,
        },
      },
      update: {
        channelName: packet.Channel,
        stateCode: packet.ChannelStateDesc,
      },
      create: {
        callId: session.callId,
        tenantId,
        linkedid,
        uniqueid,
        legType: 'inbound',
        channelName: packet.Channel ?? null,
        endpoint: packet.Channel ?? null,
        stateCode: packet.ChannelStateDesc ?? null,
        startedAt: new Date(),
      },
    });
  }

  private async onQueueJoin(packet: AmiEventPacket, tenantId: string, linkedid: string) {
    if (!linkedid) return;

    const session = await this.ensureSession(tenantId, linkedid, packet);

    await this.prisma.callSession.update({
      where: { callId: session.callId },
      data: {
        sessionStatus: 'QUEUED',
        queueName: packet.Queue ?? session.queueName,
        queuedAt: new Date(),
      },
    });

    await this.prisma.queueEvent.create({
      data: {
        callId: session.callId,
        tenantId,
        linkedid,
        queueName: packet.Queue ?? 'unknown',
        eventType: 'JOIN',
        eventTime: new Date(),
        rawPayload: packet as any,
      },
    });

    this.realtimeGateway.emitToTenant(tenantId, 'call.updated', {
      callId: session.callId,
      linkedid,
      sessionStatus: 'QUEUED',
      queueName: packet.Queue ?? null,
    });
  }

  private async onAgentCalled(packet: AmiEventPacket, tenantId: string, linkedid: string) {
    if (!linkedid) return;

    const session = await this.ensureSession(tenantId, linkedid, packet);

    await this.prisma.callSession.update({
      where: { callId: session.callId },
      data: {
        sessionStatus: 'RINGING_AGENT',
        ringingAt: new Date(),
      },
    });

    await this.prisma.queueEvent.create({
      data: {
        callId: session.callId,
        tenantId,
        linkedid,
        queueName: packet.Queue ?? session.queueName ?? 'unknown',
        eventType: 'AGENT_CALLED',
        eventTime: new Date(),
        rawPayload: packet as any,
      },
    });

    this.realtimeGateway.emitToTenant(tenantId, 'call.updated', {
      callId: session.callId,
      linkedid,
      sessionStatus: 'RINGING_AGENT',
      agentChannel: packet.DestChannel ?? null,
    });
  }

  private async onTalking(packet: AmiEventPacket, tenantId: string, linkedid: string) {
    if (!linkedid) return;

    const session = await this.ensureSession(tenantId, linkedid, packet);

    await this.prisma.callSession.update({
      where: { callId: session.callId },
      data: {
        sessionStatus: 'TALKING',
        answeredAt: session.answeredAt ?? new Date(),
      },
    });

    this.realtimeGateway.emitToTenant(tenantId, 'call.updated', {
      callId: session.callId,
      linkedid,
      sessionStatus: 'TALKING',
      answeredAt: new Date(),
    });
  }

  private async onHangup(
    _packet: AmiEventPacket,
    tenantId: string,
    linkedid: string,
    uniqueid: string | null,
  ) {
    if (!linkedid) return;

    const session = await this.prisma.callSession.findFirst({
      where: { tenantId, linkedid },
    });
    if (!session) return;

    if (uniqueid) {
      await this.prisma.callLeg.updateMany({
        where: {
          tenantId,
          uniqueid,
          endedAt: null,
        },
        data: {
          endedAt: new Date(),
        },
      });
    }

    await this.prisma.callSession.update({
      where: { callId: session.callId },
      data: {
        sessionStatus: 'ENDED',
        endedAt: new Date(),
      },
    });

    this.realtimeGateway.emitToTenant(tenantId, 'call.ended', {
      callId: session.callId,
      linkedid,
      endedAt: new Date(),
    });
  }

  private async onAgentComplete(packet: AmiEventPacket, tenantId: string, linkedid: string) {
    if (!linkedid) return;

    const session = await this.prisma.callSession.findFirst({
      where: { tenantId, linkedid },
    });
    if (!session) return;

    await this.prisma.queueEvent.create({
      data: {
        callId: session.callId,
        tenantId,
        linkedid,
        queueName: packet.Queue ?? session.queueName ?? 'unknown',
        eventType: 'AGENT_COMPLETE',
        eventTime: new Date(),
        rawPayload: packet as any,
      },
    });
  }
}
