# 18. seed

설계서상 DEV/PoC 단계에서 샘플 상담원, Queue, 고객 데이터를 두고 진행하는 흐름에 맞게 seed를 두는 것이 자연스럽습니다. fileciteturn0file1

## src/seed/seed.service.ts

```ts
import { Injectable } from '@nestjs/common';
import * as bcrypt from 'bcrypt';
import { PrismaService } from '../prisma/prisma.service';

@Injectable()
export class SeedService {
  constructor(private readonly prisma: PrismaService) {}

  async run() {
    const tenant = await this.prisma.tenant.upsert({
      where: { tenantCode: 'main' },
      update: {},
      create: {
        tenantCode: 'main',
        tenantName: 'Main Contact Center',
        timezone: 'Asia/Seoul',
      },
    });

    const passwordHash = await bcrypt.hash('password123!', 10);

    const queue = await this.prisma.queue.upsert({
      where: {
        tenantId_queueName: {
          tenantId: tenant.tenantId,
          queueName: 'sales',
        },
      },
      update: {},
      create: {
        tenantId: tenant.tenantId,
        queueName: 'sales',
        queueExten: '6001',
        queueDisplayName: '영업 대표 큐',
      },
    });

    const agent1001 = await this.prisma.agent.upsert({
      where: {
        tenantId_loginId: {
          tenantId: tenant.tenantId,
          loginId: 'agent1001',
        },
      },
      update: {},
      create: {
        tenantId: tenant.tenantId,
        loginId: 'agent1001',
        loginPasswordHash: passwordHash,
        agentCode: 'A1001',
        agentName: '상담원1001',
        extension: '1001',
        sipEndpoint: 'PJSIP/1001',
        role: 'agent',
      },
    });

    const agent1002 = await this.prisma.agent.upsert({
      where: {
        tenantId_loginId: {
          tenantId: tenant.tenantId,
          loginId: 'agent1002',
        },
      },
      update: {},
      create: {
        tenantId: tenant.tenantId,
        loginId: 'agent1002',
        loginPasswordHash: passwordHash,
        agentCode: 'A1002',
        agentName: '상담원1002',
        extension: '1002',
        sipEndpoint: 'PJSIP/1002',
        role: 'agent',
      },
    });

    await this.prisma.queueAgentMember.upsert({
      where: {
        queueId_agentId: {
          queueId: queue.queueId,
          agentId: agent1001.agentId,
        },
      },
      update: {},
      create: {
        tenantId: tenant.tenantId,
        queueId: queue.queueId,
        agentId: agent1001.agentId,
      },
    });

    await this.prisma.queueAgentMember.upsert({
      where: {
        queueId_agentId: {
          queueId: queue.queueId,
          agentId: agent1002.agentId,
        },
      },
      update: {},
      create: {
        tenantId: tenant.tenantId,
        queueId: queue.queueId,
        agentId: agent1002.agentId,
      },
    });

    const customer = await this.prisma.customer.create({
      data: {
        tenantId: tenant.tenantId,
        customerCode: 'CUST001',
        customerName: '김고객',
        grade: 'VIP',
      },
    });

    await this.prisma.customerPhone.create({
      data: {
        customerId: customer.customerId,
        phoneNumber: '01012345678',
        normalizedPhone: '01012345678',
        isPrimary: true,
      },
    });

    return {
      tenant,
      queue,
      agents: [agent1001, agent1002],
      customer,
    };
  }
}
```

