# 7. AMI 이벤트 정규화 매퍼

이 파일이 핵심입니다.  
설계서의 `Newchannel`, `Newstate`, `DialBegin/DialEnd`, `QueueCallerJoin`, `AgentCalled`, `AgentConnect`, `BridgeEnter`, `BridgeLeave`, `Hangup`, `AgentComplete`를 실제 정규화 이벤트로 변환합니다. fileciteturn1file1turn1file2

## `src/modules/calls/ami-event.mapper.ts`

```ts
import { Injectable } from '@nestjs/common';
import {
  LegType,
  NormalizedEventType,
  SessionStatus,
} from './call.enums';
import { AmiEventPayload, NormalizedCallEvent } from './ami-event.types';

@Injectable()
export class AmiEventMapper {
  map(event: AmiEventPayload): NormalizedCallEvent | null {
    const linkedid = event.Linkedid || event.Uniqueid;
    if (!linkedid) return null;

    const at = new Date();
    const eventName = event.Event;

    switch (eventName) {
      case 'Newchannel':
        return {
          type: NormalizedEventType.CALL_CREATED,
          linkedid,
          uniqueid: event.Uniqueid,
          channel: event.Channel,
          legType: this.inferLegType(event.Channel),
          ani: event.CallerIDNum,
          dnis: event.Exten,
          nextSessionStatus: SessionStatus.NEW,
          at,
          meta: { rawEvent: eventName },
        };

      case 'Newstate': {
        const state = event.ChannelStateDesc;
        if (state === 'Ringing' && this.inferLegType(event.Channel) === LegType.AGENT) {
          return {
            type: NormalizedEventType.CALL_AGENT_RINGING,
            linkedid,
            uniqueid: event.Uniqueid,
            channel: event.Channel,
            legType: LegType.AGENT,
            nextSessionStatus: SessionStatus.RINGING_AGENT,
            at,
            meta: { rawEvent: eventName, state },
          };
        }

        if (state === 'Up') {
          return {
            type: NormalizedEventType.CALL_BRIDGED,
            linkedid,
            uniqueid: event.Uniqueid,
            channel: event.Channel,
            legType: this.inferLegType(event.Channel),
            nextSessionStatus: SessionStatus.TALKING,
            at,
            meta: { rawEvent: eventName, state },
          };
        }

        return null;
      }

      case 'QueueCallerJoin':
        return {
          type: NormalizedEventType.CALL_QUEUED,
          linkedid,
          uniqueid: event.Uniqueid,
          queueName: event.Queue,
          channel: event.Channel,
          nextSessionStatus: SessionStatus.QUEUED,
          at,
          meta: { rawEvent: eventName },
        };

      case 'AgentCalled':
        return {
          type: NormalizedEventType.CALL_AGENT_OFFERED,
          linkedid,
          uniqueid: event.Uniqueid,
          queueName: event.Queue,
          channel: event.Interface || event.MemberName,
          agentExtension: this.extractExtension(event.Interface || event.MemberName),
          nextSessionStatus: SessionStatus.RINGING_AGENT,
          at,
          meta: { rawEvent: eventName },
        };

      case 'AgentConnect':
        return {
          type: NormalizedEventType.CALL_ANSWERED,
          linkedid,
          uniqueid: event.Uniqueid,
          queueName: event.Queue,
          channel: event.Channel,
          nextSessionStatus: SessionStatus.TALKING,
          at,
          meta: { rawEvent: eventName },
        };

      case 'BridgeEnter':
        return {
          type: NormalizedEventType.CALL_BRIDGED,
          linkedid,
          uniqueid: event.Uniqueid,
          channel: event.Channel,
          nextSessionStatus: SessionStatus.TALKING,
          at,
          meta: {
            rawEvent: eventName,
            bridgeUniqueid: event.BridgeUniqueid,
          },
        };

      case 'BridgeLeave':
        return {
          type: NormalizedEventType.CALL_TRANSFER_PROGRESS,
          linkedid,
          uniqueid: event.Uniqueid,
          channel: event.Channel,
          at,
          meta: { rawEvent: eventName },
        };

      case 'DialBegin':
        return {
          type: NormalizedEventType.CALL_TRANSFER_PROGRESS,
          linkedid,
          uniqueid: event.Uniqueid,
          channel: event.Channel,
          nextSessionStatus: SessionStatus.TRANSFERRING,
          at,
          meta: {
            rawEvent: eventName,
            destination: event.Destination,
          },
        };

      case 'DialEnd':
        return {
          type:
            event.DialStatus === 'ANSWER'
              ? NormalizedEventType.CALL_BRIDGED
              : NormalizedEventType.CALL_TRANSFER_FAILED,
          linkedid,
          uniqueid: event.Uniqueid,
          channel: event.Channel,
          nextSessionStatus:
            event.DialStatus === 'ANSWER'
              ? SessionStatus.TALKING
              : SessionStatus.TRANSFERRING,
          at,
          meta: {
            rawEvent: eventName,
            dialStatus: event.DialStatus,
          },
        };

      case 'Hold':
        return {
          type: NormalizedEventType.CALL_HOLD_STARTED,
          linkedid,
          uniqueid: event.Uniqueid,
          channel: event.Channel,
          nextSessionStatus: SessionStatus.HOLD,
          at,
          meta: { rawEvent: eventName },
        };

      case 'Unhold':
        return {
          type: NormalizedEventType.CALL_HOLD_ENDED,
          linkedid,
          uniqueid: event.Uniqueid,
          channel: event.Channel,
          nextSessionStatus: SessionStatus.TALKING,
          at,
          meta: { rawEvent: eventName },
        };

      case 'Hangup':
        return {
          type: NormalizedEventType.CALL_ENDED,
          linkedid,
          uniqueid: event.Uniqueid,
          channel: event.Channel,
          nextSessionStatus: SessionStatus.ENDED,
          at,
          meta: {
            rawEvent: eventName,
            cause: event.Cause,
            causeText: event['Cause-txt'],
          },
        };

      case 'AgentComplete':
        return {
          type: NormalizedEventType.CALL_ACW_STARTED,
          linkedid,
          uniqueid: event.Uniqueid,
          queueName: event.Queue,
          nextSessionStatus: SessionStatus.AFTER_CALL_WORK,
          at,
          meta: { rawEvent: eventName },
        };

      default:
        return null;
    }
  }

  private inferLegType(channel?: string): LegType {
    if (!channel) return LegType.LOCAL;
    if (channel.startsWith('Local/')) return LegType.LOCAL;
    if (channel.includes('from-queue')) return LegType.LOCAL;
    if (channel.startsWith('PJSIP/') && /^\d+/.test(channel.split('/')[1] ?? '')) {
      return LegType.AGENT;
    }
    if (channel.startsWith('PJSIP/')) return LegType.INBOUND;
    if (channel.startsWith('SIP/')) return LegType.INBOUND;
    return LegType.LOCAL;
  }

  private extractExtension(value?: string): string | undefined {
    if (!value) return undefined;
    const match = value.match(/(\d{3,6})/);
    return match?.[1];
  }
}
```

