# 8. 세션 리듀서

이 파일은 **idempotent**, **linkedid 중심**, **종료 판정 보수적 처리**가 핵심입니다. 설계서가 요구한 정합성 원칙과 맞닿아 있습니다. fileciteturn1file1

## `src/modules/calls/call-session.reducer.ts`

```ts
import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import {
  LegType,
  NormalizedEventType,
  SessionStatus,
} from './call.enums';
import { AmiEventPayload, NormalizedCallEvent } from './ami-event.types';

@Injectable()
export class CallSessionReducer {
  private readonly logger = new Logger(CallSessionReducer.name);

  constructor(private readonly prisma: PrismaService) {}

  async persistRawEvent(tenantId: string, event: AmiEventPayload): Promise<void> {
    const linkedid = event.Linkedid || event.Uniqueid || null;
    const uniqueid = event.Uniqueid || null;

    await this.prisma.rawAmiEvent.create({
      data: {
        tenantId,
        linkedid,
        uniqueid,
        eventName: event.Event,
        eventTime: new Date(),
        payload: event as unknown as object,
      },
    });
  }

  async applyNormalizedEvent(
    tenantId: string,
    event: AmiEventPayload,
    normalized: NormalizedCallEvent | null,
  ): Promise<void> {
    if (!normalized) return;

    const linkedid = normalized.linkedid;
    let session = await this.prisma.callSession.findUnique({
      where: {
        tenantId_linkedid: { tenantId, linkedid },
      },
    });

    if (!session) {
      session = await this.prisma.callSession.create({
        data: {
          tenantId,
          linkedid,
          direction: this.inferDirection(normalized),
          ani: normalized.ani,
          aniNormalized: this.normalizePhone(normalized.ani),
          dnis: normalized.dnis,
          queueName: normalized.queueName,
          sessionStatus: normalized.nextSessionStatus ?? SessionStatus.NEW,
          startedAt: normalized.at,
        },
      });
    }

    if (normalized.uniqueid) {
      await this.upsertLeg(tenantId, session.callId, normalized, event);
    }

    switch (normalized.type) {
      case NormalizedEventType.CALL_QUEUED:
        await this.prisma.queueEvent.create({
          data: {
            callId: session.callId,
            tenantId,
            linkedid,
            queueName: normalized.queueName ?? 'unknown',
            eventType: 'JOIN',
            eventTime: normalized.at,
            rawPayload: event as unknown as object,
          },
        });

        await this.prisma.callSession.update({
          where: { callId: session.callId },
          data: {
            queueName: normalized.queueName,
            queuedAt: session.queuedAt ?? normalized.at,
            sessionStatus: SessionStatus.QUEUED,
            updatedAt: new Date(),
          },
        });
        break;

      case NormalizedEventType.CALL_AGENT_OFFERED:
      case NormalizedEventType.CALL_AGENT_RINGING:
        await this.prisma.callSession.update({
          where: { callId: session.callId },
          data: {
            ringingAt: session.ringingAt ?? normalized.at,
            sessionStatus: SessionStatus.RINGING_AGENT,
            updatedAt: new Date(),
          },
        });
        break;

      case NormalizedEventType.CALL_ANSWERED:
      case NormalizedEventType.CALL_BRIDGED:
        await this.prisma.callSession.update({
          where: { callId: session.callId },
          data: {
            answeredAt: session.answeredAt ?? normalized.at,
            sessionStatus: SessionStatus.TALKING,
            updatedAt: new Date(),
          },
        });
        break;

      case NormalizedEventType.CALL_HOLD_STARTED:
        await this.prisma.callSession.update({
          where: { callId: session.callId },
          data: {
            sessionStatus: SessionStatus.HOLD,
            updatedAt: new Date(),
          },
        });
        break;

      case NormalizedEventType.CALL_HOLD_ENDED:
        await this.prisma.callSession.update({
          where: { callId: session.callId },
          data: {
            sessionStatus: SessionStatus.TALKING,
            updatedAt: new Date(),
          },
        });
        break;

      case NormalizedEventType.CALL_TRANSFER_PROGRESS:
        await this.prisma.callSession.update({
          where: { callId: session.callId },
          data: {
            transferFlag: true,
            sessionStatus: SessionStatus.TRANSFERRING,
            updatedAt: new Date(),
          },
        });
        break;

      case NormalizedEventType.CALL_ACW_STARTED:
        await this.prisma.queueEvent.create({
          data: {
            callId: session.callId,
            tenantId,
            linkedid,
            queueName: session.queueName ?? 'unknown',
            eventType: 'AGENT_COMPLETE',
            eventTime: normalized.at,
            rawPayload: event as unknown as object,
          },
        });

        await this.prisma.callSession.update({
          where: { callId: session.callId },
          data: {
            sessionStatus: SessionStatus.AFTER_CALL_WORK,
            updatedAt: new Date(),
          },
        });
        break;

      case NormalizedEventType.CALL_ENDED: {
        const activeLegs = await this.prisma.callLeg.count({
          where: {
            tenantId,
            linkedid,
            endedAt: null,
          },
        });

        if (activeLegs <= 1) {
          await this.prisma.callSession.update({
            where: { callId: session.callId },
            data: {
              endedAt: normalized.at,
              sessionStatus: SessionStatus.ENDED,
              updatedAt: new Date(),
            },
          });
        }
        break;
      }

      default:
        break;
    }
  }

  private async upsertLeg(
    tenantId: string,
    callId: string,
    normalized: NormalizedCallEvent,
    raw: AmiEventPayload,
  ): Promise<void> {
    const uniqueid = normalized.uniqueid!;
    const existing = await this.prisma.callLeg.findUnique({
      where: {
        tenantId_uniqueid: { tenantId, uniqueid },
      },
    });

    const legType = normalized.legType ?? this.inferLegTypeFromRaw(raw);

    if (!existing) {
      await this.prisma.callLeg.create({
        data: {
          callId,
          tenantId,
          linkedid: normalized.linkedid,
          uniqueid,
          parentUniqueid: raw.Linkedid !== raw.Uniqueid ? raw.Linkedid : null,
          legType,
          channelName: raw.Channel,
          bridgedChannelName: raw.DestChannel,
          endpoint: this.extractEndpoint(raw.Channel),
          stateCode: raw.ChannelStateDesc,
          dialStatus: raw.DialStatus,
          startedAt: normalized.at,
          bridgedAt:
            normalized.type === NormalizedEventType.CALL_BRIDGED ? normalized.at : null,
          endedAt:
            normalized.type === NormalizedEventType.CALL_ENDED ? normalized.at : null,
        },
      });
      return;
    }

    await this.prisma.callLeg.update({
      where: { legId: existing.legId },
      data: {
        stateCode: raw.ChannelStateDesc ?? existing.stateCode,
        dialStatus: raw.DialStatus ?? existing.dialStatus,
        bridgedChannelName: raw.DestChannel ?? existing.bridgedChannelName,
        bridgedAt:
          normalized.type === NormalizedEventType.CALL_BRIDGED
            ? existing.bridgedAt ?? normalized.at
            : existing.bridgedAt,
        endedAt:
          normalized.type === NormalizedEventType.CALL_ENDED
            ? existing.endedAt ?? normalized.at
            : existing.endedAt,
      },
    });
  }

  private inferDirection(normalized: NormalizedCallEvent): 'inbound' | 'outbound' | 'internal' {
    if (normalized.ani && normalized.dnis) return 'inbound';
    return 'outbound';
  }

  private normalizePhone(value?: string): string | undefined {
    return value?.replace(/\D/g, '');
  }

  private extractEndpoint(channel?: string): string | undefined {
    if (!channel) return undefined;
    const parts = channel.split('/');
    return parts[1]?.split('-')[0];
  }

  private inferLegTypeFromRaw(raw: AmiEventPayload): LegType {
    const channel = raw.Channel ?? '';
    if (channel.startsWith('Local/')) return LegType.LOCAL;
    if (channel.startsWith('PJSIP/') && /^\d+/.test(channel.split('/')[1] ?? '')) {
      return LegType.AGENT;
    }
    if (raw.Event === 'DialBegin') return LegType.OUTBOUND;
    return LegType.INBOUND;
  }
}
