# 10. Command Service

originate / hangup / transfer의 실질적인 핵심입니다.  
특히 REST 성공이 곧 통화 성공이 아니라 **요청 accepted** 기준으로 응답하도록 설계했습니다. 이 방식이 기존 API/실시간 이벤트 분리 원칙과 잘 맞습니다. fileciteturn1file2

## `src/modules/calls/call-command.service.ts`

```ts
import {
  BadRequestException,
  ForbiddenException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { AmiClientService } from '../ami/ami-client.service';
import { CommandStatus, TransferTargetType, TransferType } from './call.enums';
import {
  CallOriginateRequestDto,
  CallOriginateResponseDto,
} from './dto/call-originate.dto';
import { CallHangupResponseDto } from './dto/call-hangup.dto';
import {
  CallTransferRequestDto,
  CallTransferResponseDto,
} from './dto/call-transfer.dto';

@Injectable()
export class CallCommandService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly amiClient: AmiClientService,
  ) {}

  async originate(
    tenantId: string,
    dto: CallOriginateRequestDto,
  ): Promise<CallOriginateResponseDto> {
    const agent = await this.prisma.agent.findFirst({
      where: {
        tenantId,
        agentId: dto.agentId,
        extension: dto.extension,
        isActive: true,
      },
    });

    if (!agent) {
      throw new NotFoundException('AGENT_NOT_FOUND');
    }

    const activeCall = await this.prisma.callSession.findFirst({
      where: {
        tenantId,
        primaryAgentId: dto.agentId,
        endedAt: null,
      },
    });

    if (activeCall) {
      throw new BadRequestException('AGENT_ALREADY_ON_CALL');
    }

    const linkedid = `${Date.now()}`;
    const session = await this.prisma.callSession.create({
      data: {
        tenantId,
        linkedid,
        direction: 'outbound',
        ani: dto.extension,
        aniNormalized: dto.extension,
        dnis: dto.phoneNumber,
        customerId: dto.customerId,
        primaryAgentId: dto.agentId,
        sessionStatus: 'NEW',
        campaignCode: dto.campaignCode,
        startedAt: new Date(),
      },
    });

    const result = await this.amiClient.originate({
      channel: `PJSIP/${dto.extension}`,
      context: 'outbound-clicktocall',
      exten: dto.phoneNumber,
      priority: 1,
      callerId: dto.extension,
      variables: {
        __TENANT_ID: tenantId,
        __CALL_LINKEDID: linkedid,
        __AGENT_ID: dto.agentId,
        __CUSTOMER_ID: dto.customerId ?? '',
        __TARGET_NUMBER: dto.phoneNumber,
      },
    });

    return {
      requestId: result.actionId,
      callId: session.callId,
      linkedid,
      commandStatus: result.success ? CommandStatus.ACCEPTED : CommandStatus.FAILED,
      failReason: result.success ? undefined : result.message,
    };
  }

  async hangup(tenantId: string, callId: string, requesterAgentId: string): Promise<CallHangupResponseDto> {
    const session = await this.prisma.callSession.findFirst({
      where: { tenantId, callId },
      include: { legs: true },
    });

    if (!session) throw new NotFoundException('CALL_NOT_FOUND');
    if (session.endedAt) throw new BadRequestException('CALL_ALREADY_ENDED');

    if (session.primaryAgentId && session.primaryAgentId !== requesterAgentId) {
      throw new ForbiddenException('INSUFFICIENT_PERMISSION');
    }

    const targetLeg =
      session.legs.find((leg) => !leg.endedAt && leg.agentId === requesterAgentId) ??
      session.legs.find((leg) => !leg.endedAt) ??
      null;

    if (!targetLeg?.channelName) {
      throw new BadRequestException('HANGUP_TARGET_NOT_ACTIVE');
    }

    const result = await this.amiClient.hangup({
      channel: targetLeg.channelName,
    });

    return {
      callId,
      requestedAction: 'HANGUP',
      targetChannel: targetLeg.channelName,
      commandStatus: result.success ? CommandStatus.ACCEPTED : CommandStatus.FAILED,
      message: result.message,
    };
  }

  async transfer(
    tenantId: string,
    callId: string,
    requesterAgentId: string,
    dto: CallTransferRequestDto,
  ): Promise<CallTransferResponseDto> {
    const session = await this.prisma.callSession.findFirst({
      where: { tenantId, callId },
      include: { legs: true },
    });

    if (!session) throw new NotFoundException('CALL_NOT_FOUND');
    if (session.endedAt) throw new BadRequestException('CALL_ALREADY_ENDED');
    if (session.primaryAgentId && session.primaryAgentId !== requesterAgentId) {
      throw new ForbiddenException('INSUFFICIENT_PERMISSION');
    }

    const activeAgentLeg = session.legs.find((leg) => !leg.endedAt && !!leg.channelName);
    if (!activeAgentLeg?.channelName) {
      throw new BadRequestException('TRANSFER_NOT_ALLOWED');
    }

    const transfer = await this.prisma.callTransfer.create({
      data: {
        callId,
        tenantId,
        linkedid: session.linkedid,
        transferType: dto.transferType,
        fromAgentId: requesterAgentId,
        fromExtension: session.ani ?? undefined,
        toExtension: dto.target,
        requestedAt: new Date(),
        transferResult: 'REQUESTED',
      },
    });

    let actionResult: { success: boolean; message?: string };

    if (
      dto.transferType === TransferType.BLIND &&
      dto.targetType === TransferTargetType.EXTENSION
    ) {
      actionResult = await this.amiClient.redirect({
        channel: activeAgentLeg.channelName,
        context: 'from-transfer',
        exten: dto.target,
        priority: 1,
      });
    } else if (
      dto.transferType === TransferType.QUEUE &&
      dto.targetType === TransferTargetType.QUEUE
    ) {
      actionResult = await this.amiClient.redirect({
        channel: activeAgentLeg.channelName,
        context: 'queue-entry',
        exten: 's',
        priority: 1,
      });
    } else {
      actionResult = { success: true, message: 'Transfer accepted for async workflow' };
    }

    await this.prisma.callSession.update({
      where: { callId },
      data: {
        transferFlag: true,
        sessionStatus: 'TRANSFERRING',
      },
    });

    return {
      callId,
      transferId: transfer.transferId,
      transferType: dto.transferType,
      targetType: dto.targetType,
      target: dto.target,
      commandStatus: actionResult.success
        ? CommandStatus.ACCEPTED
        : CommandStatus.FAILED,
      requestedAt: transfer.requestedAt.toISOString(),
      failReason: actionResult.success ? undefined : actionResult.message,
    };
  }
}
