# 3) AMI TCP Client

## `src/ami/ami.client.ts`

```ts
import {
  Injectable,
  Logger,
  OnModuleDestroy,
  OnModuleInit,
} from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { EventEmitter } from 'events';
import * as net from 'net';
import { AmiMessage } from './types/ami-event.type';

@Injectable()
export class AmiClient extends EventEmitter implements OnModuleInit, OnModuleDestroy {
  private readonly logger = new Logger(AmiClient.name);
  private socket: net.Socket | null = null;
  private buffer = '';
  private connected = false;
  private reconnectTimer: NodeJS.Timeout | null = null;
  private pingTimer: NodeJS.Timeout | null = null;
  private actionSeq = 0;

  constructor(private readonly configService: ConfigService) {
    super();
  }

  async onModuleInit(): Promise<void> {
    await this.connect();
  }

  async onModuleDestroy(): Promise<void> {
    this.cleanup();
  }

  async connect(): Promise<void> {
    if (this.socket) {
      return;
    }

    const host = this.configService.get<string>('AMI_HOST', '127.0.0.1');
    const port = Number(this.configService.get<string>('AMI_PORT', '5038'));

    this.logger.log(`Connecting to AMI ${host}:${port}`);

    this.socket = net.createConnection({ host, port });

    this.socket.on('connect', () => {
      this.connected = true;
      this.logger.log('AMI socket connected');
    });

    this.socket.on('data', (chunk: Buffer) => {
      this.buffer += chunk.toString('utf8');
      this.flushFrames();
    });

    this.socket.on('error', (error) => {
      this.logger.error(`AMI socket error: ${error.message}`, error.stack);
    });

    this.socket.on('close', () => {
      this.logger.warn('AMI socket closed');
      this.connected = false;
      this.cleanupSocketOnly();
      this.scheduleReconnect();
    });
  }

  private flushFrames(): void {
    const delimiter = '\r\n\r\n';
    while (this.buffer.includes(delimiter)) {
      const index = this.buffer.indexOf(delimiter);
      const frame = this.buffer.slice(0, index);
      this.buffer = this.buffer.slice(index + delimiter.length);

      if (!frame.trim()) {
        continue;
      }

      const message = this.parseFrame(frame);
      this.handleMessage(message);
    }
  }

  private parseFrame(frame: string): AmiMessage {
    const lines = frame.split(/\r\n/);
    const message: AmiMessage = {};

    for (const line of lines) {
      const sep = line.indexOf(':');
      if (sep === -1) {
        continue;
      }
      const key = line.slice(0, sep).trim().toLowerCase();
      const value = line.slice(sep + 1).trim();
      message[key] = value;
    }

    return message;
  }

  private handleMessage(message: AmiMessage): void {
    if (message.response === 'Success' && message.message?.includes('Authentication accepted')) {
      this.logger.log('AMI login success');
      this.startPing();
      this.emit('ready');
      return;
    }

    if (message.event) {
      this.emit('event', message);
      return;
    }

    if (message.response) {
      this.emit(`response:${message.actionid}`, message);
    }
  }

  async login(): Promise<void> {
    const username = this.configService.get<string>('AMI_USERNAME', 'cti_middleware');
    const secret = this.configService.get<string>('AMI_SECRET', '');

    await this.sendAction({
      Action: 'Login',
      Username: username,
      Secret: secret,
      Events: 'on',
    });
  }

  async sendAction(fields: Record<string, string>): Promise<AmiMessage> {
    if (!this.socket) {
      throw new Error('AMI socket not connected');
    }

    const actionId = `${Date.now()}-${++this.actionSeq}`;
    const payload = {
      ...fields,
      ActionID: actionId,
    };

    const raw = Object.entries(payload)
      .map(([key, value]) => `${key}: ${value}`)
      .join('\r\n') + '\r\n\r\n';

    const responsePromise = new Promise<AmiMessage>((resolve) => {
      this.once(`response:${actionId}`, resolve);
    });

    this.socket.write(raw, 'utf8');

    return responsePromise;
  }

  async originate(params: {
    channel: string;
    context: string;
    exten: string;
    priority?: number;
    callerId?: string;
    variable?: Record<string, string>;
    timeoutMs?: number;
    async?: boolean;
  }): Promise<AmiMessage> {
    const variable = Object.entries(params.variable ?? {})
      .map(([k, v]) => `${k}=${v}`)
      .join(',');

    return this.sendAction({
      Action: 'Originate',
      Channel: params.channel,
      Context: params.context,
      Exten: params.exten,
      Priority: String(params.priority ?? 1),
      CallerID: params.callerId ?? '',
      Variable: variable,
      Timeout: String(params.timeoutMs ?? 30000),
      Async: params.async === false ? 'false' : 'true',
    });
  }

  async hangup(channel: string): Promise<AmiMessage> {
    return this.sendAction({
      Action: 'Hangup',
      Channel: channel,
    });
  }

  async redirect(params: {
    channel: string;
    extraChannel?: string;
    context: string;
    exten: string;
    priority?: number;
  }): Promise<AmiMessage> {
    return this.sendAction({
      Action: 'Redirect',
      Channel: params.channel,
      ExtraChannel: params.extraChannel ?? '',
      Context: params.context,
      Exten: params.exten,
      Priority: String(params.priority ?? 1),
    });
  }

  private startPing(): void {
    if (this.pingTimer) {
      clearInterval(this.pingTimer);
    }

    this.pingTimer = setInterval(async () => {
      try {
        await this.sendAction({ Action: 'Ping' });
      } catch (error) {
        this.logger.warn(`AMI ping failed: ${(error as Error).message}`);
      }
    }, 15000);
  }

  private scheduleReconnect(): void {
    if (this.reconnectTimer) {
      return;
    }

    this.reconnectTimer = setTimeout(async () => {
      this.reconnectTimer = null;
      try {
        await this.connect();
        await this.login();
      } catch (error) {
        this.logger.error(`AMI reconnect failed: ${(error as Error).message}`);
        this.scheduleReconnect();
      }
    }, 3000);
  }

  private cleanupSocketOnly(): void {
    if (this.socket) {
      this.socket.removeAllListeners();
      this.socket.destroy();
      this.socket = null;
    }
  }

  private cleanup(): void {
    if (this.reconnectTimer) {
      clearTimeout(this.reconnectTimer);
      this.reconnectTimer = null;
    }
    if (this.pingTimer) {
      clearInterval(this.pingTimer);
      this.pingTimer = null;
    }
    this.cleanupSocketOnly();
  }
}
