## `src/ami/ami.listener.service.ts`

```ts
import { Injectable, Logger, OnModuleInit } from '@nestjs/common';
import { AmiClient } from './ami.client';
import { AmiMessage } from './types/ami-event.type';
import { RealtimeGateway } from '../realtime/realtime.gateway';
import { CallSessionEngineService } from '../calls/services/call-session-engine.service';

@Injectable()
export class AmiListenerService implements OnModuleInit {
  private readonly logger = new Logger(AmiListenerService.name);
  private readonly defaultTenantId = '00000000-0000-0000-0000-000000000001';

  constructor(
    private readonly amiClient: AmiClient,
    private readonly engine: CallSessionEngineService,
    private readonly realtimeGateway: RealtimeGateway,
  ) {}

  async onModuleInit(): Promise<void> {
    this.amiClient.on('ready', () => {
      this.logger.log('AMI ready');
    });

    this.amiClient.on('event', async (message: AmiMessage) => {
      try {
        const result = await this.engine.consume(message, {
          tenantId: this.defaultTenantId,
          receivedAt: new Date(),
        });

        if (result?.broadcast) {
          this.realtimeGateway.broadcastCallUpdated(result.broadcast);
        }

        if (result?.queueSummary) {
          this.realtimeGateway.broadcastQueueSummaryUpdated(result.queueSummary);
        }
      } catch (error) {
        this.logger.error(
          `Failed to process AMI event ${message.event}: ${(error as Error).message}`,
          (error as Error).stack,
        );
      }
    });

    await this.amiClient.login();
  }
}
