export function normalizePhone(phone?: string): string | null {
  if (!phone) return null;
  const normalized = phone.replace(/[^\d+]/g, '');
  return normalized.length ? normalized : null;
}

export function extractEndpointFromChannel(channel?: string): string | null {
  if (!channel) return null;
  const match = channel.match(/^(PJSIP|SIP|Local)\/([^-/;]+)/i);
  return match?.[2] ?? null;
}

export function getLinkedid(payload: Record<string, any>): string | null {
  return payload.linkedid || payload.destlinkedid || payload.originatorlinkedid || null;
}

export function getUniqueid(payload: Record<string, any>): string | null {
  return payload.uniqueid || payload.destuniqueid || payload.srcuniqueid || null;
}

export function parseAmiDate(input?: string): Date {
  if (!input) return new Date();
  const asNumber = Number(input);
  if (!Number.isNaN(asNumber) && asNumber > 0) {
    return new Date(asNumber * 1000);
  }
  const date = new Date(input);
  return Number.isNaN(date.getTime()) ? new Date() : date;
}
