# 6) Session Engine 핵심

## `src/calls/services/call-session-engine.service.ts`

```ts
import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { SessionStatus, TransferType, QueueEventType, LegType } from '@prisma/client';
import { AmiMessage, AmiEventContext } from '../../ami/types/ami-event.type';
import {
  extractEndpointFromChannel,
  getLinkedid,
  normalizePhone,
  parseAmiDate,
} from '../utils/ami.util';
import { QueueSummaryService } from '../../queues/queue-summary.service';

@Injectable()
export class CallSessionEngineService {
  private readonly logger = new Logger(CallSessionEngineService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly queueSummaryService: QueueSummaryService,
  ) {}

  async consume(message: AmiMessage, context: AmiEventContext): Promise<any> {
    const eventName = message.event ?? 'Unknown';
    const eventTime = parseAmiDate(message.timestamp);
    const linkedid = getLinkedid(message);
    const uniqueid = message.uniqueid ?? null;

    let callId: string | null = null;

    if (linkedid) {
      const session = await this.ensureSessionFromEvent(message, context, eventTime, linkedid);
      callId = session.id;
    }

    await this.prisma.rawAmiEvent.create({
      data: {
        tenantId: context.tenantId,
        callId,
        linkedid: linkedid ?? undefined,
        uniqueid: uniqueid ?? undefined,
        eventName,
        eventTime,
        payload: message as any,
      },
    });

    switch (eventName) {
      case 'Newchannel':
        return this.handleNewchannel(message, context, eventTime, linkedid);
      case 'Newstate':
        return this.handleNewstate(message, context, eventTime, linkedid);
      case 'DialBegin':
      case 'DialEnd':
        return this.handleDial(message, context, eventTime, linkedid);
      case 'QueueCallerJoin':
      case 'QueueCallerLeave':
      case 'AgentCalled':
      case 'AgentConnect':
      case 'AgentComplete':
        return this.handleQueueEvent(message, context, eventTime, linkedid);
      case 'BridgeEnter':
      case 'BridgeLeave':
        return this.handleBridgeEvent(message, context, eventTime, linkedid);
      case 'Hold':
      case 'Unhold':
        return this.handleHoldEvent(message, context, eventTime, linkedid);
      case 'Hangup':
        return this.handleHangup(message, context, eventTime, linkedid);
      case 'BlindTransfer':
        return this.handleTransfer(message, context, eventTime, linkedid, 'blind');
      case 'AttendedTransfer':
        return this.handleTransfer(message, context, eventTime, linkedid, 'attended');
      default:
        return null;
    }
  }

  private async ensureSessionFromEvent(
    message: AmiMessage,
    context: AmiEventContext,
    eventTime: Date,
    linkedid: string,
  ) {
    const existing = await this.prisma.callSession.findUnique({
      where: { linkedid },
    });
    if (existing) return existing;

    const ani = normalizePhone(message.calleridnum || message.connectedlinenum || message.ani);
    const dnis = normalizePhone(message.exten || message.dnis);
    const queueName = message.queue ?? message.queuename ?? undefined;

    return this.prisma.callSession.create({
      data: {
        tenantId: context.tenantId,
        linkedid,
        direction: dnis ? 'inbound' : 'internal',
        ani: ani ?? undefined,
        aniNormalized: ani ?? undefined,
        dnis: dnis ?? undefined,
        queueName,
        sessionStatus: SessionStatus.NEW,
        startedAt: eventTime,
      },
    });
  }

  private async handleNewchannel(
    message: AmiMessage,
    context: AmiEventContext,
    eventTime: Date,
    linkedid: string | null,
  ) {
    if (!linkedid || !message.uniqueid) return null;

    const session = await this.ensureSessionFromEvent(message, context, eventTime, linkedid);
    const endpoint = extractEndpointFromChannel(message.channel);
    const legType: LegType =
      endpoint === null
        ? LegType.inbound
        : message.channel?.startsWith('Local/')
          ? LegType.local
          : LegType.agent;

    await this.prisma.callLeg.upsert({
      where: { uniqueid: message.uniqueid },
      create: {
        callId: session.id,
        tenantId: context.tenantId,
        linkedid,
        uniqueid: message.uniqueid,
        parentUniqueid: message.linkedid && message.linkedid !== message.uniqueid ? message.linkedid : undefined,
        legType,
        channelName: message.channel,
        endpoint: endpoint ?? undefined,
        stateCode: message.channelstate || message.channelstatedesc,
        startedAt: eventTime,
      },
      update: {
        channelName: message.channel,
        endpoint: endpoint ?? undefined,
        stateCode: message.channelstate || message.channelstatedesc,
      },
    });

    return this.snapshotBroadcast(session.id);
  }

  private async handleNewstate(
    message: AmiMessage,
    context: AmiEventContext,
    eventTime: Date,
    linkedid: string | null,
  ) {
    if (!linkedid) return null;

    const stateDesc = message.channelstatedesc?.toUpperCase();
    if (stateDesc === 'RINGING') {
      const session = await this.prisma.callSession.update({
        where: { linkedid },
        data: {
          sessionStatus: SessionStatus.RINGING_AGENT,
          ringingAt: eventTime,
        },
      });
      return this.snapshotBroadcast(session.id);
    }

    if (stateDesc === 'UP') {
      const session = await this.prisma.callSession.update({
        where: { linkedid },
        data: {
          sessionStatus: SessionStatus.TALKING,
          answeredAt: eventTime,
        },
      });
      return this.snapshotBroadcast(session.id);
    }

    return null;
  }

  private async handleDial(
    message: AmiMessage,
    context: AmiEventContext,
    eventTime: Date,
    linkedid: string | null,
  ) {
    if (!linkedid) return null;

    if (message.event === 'DialEnd' && message.dialstatus) {
      const destUniqueId = message.destuniqueid;
      if (destUniqueId) {
        await this.prisma.callLeg.updateMany({
          where: { uniqueid: destUniqueId },
          data: { dialStatus: message.dialstatus },
        });
      }
    }

    return null;
  }

  private async handleQueueEvent(
    message: AmiMessage,
    context: AmiEventContext,
    eventTime: Date,
    linkedid: string | null,
  ) {
    if (!linkedid) return null;

    const session = await this.prisma.callSession.findUniqueOrThrow({
      where: { linkedid },
    });

    const queueName = message.queue || message.queuename || session.queueName || 'default';
    const agentExtension = this.extractAgentExtension(message);

    let eventType: QueueEventType | null = null;
    let nextStatus: SessionStatus | null = null;
    let abandonFlag: boolean | undefined;

    switch (message.event) {
      case 'QueueCallerJoin':
        eventType = QueueEventType.JOIN;
        nextStatus = SessionStatus.QUEUED;
        break;
      case 'QueueCallerLeave':
        eventType = QueueEventType.LEAVE;
        break;
      case 'AgentCalled':
        eventType = QueueEventType.AGENT_CALLED;
        nextStatus = SessionStatus.RINGING_AGENT;
        break;
      case 'AgentConnect':
        eventType = QueueEventType.AGENT_CONNECT;
        nextStatus = SessionStatus.TALKING;
        break;
      case 'AgentComplete':
        eventType = QueueEventType.AGENT_COMPLETE;
        nextStatus = SessionStatus.AFTER_CALL_WORK;
        break;
    }

    if (!eventType) return null;

    await this.prisma.queueEvent.create({
      data: {
        callId: session.id,
        tenantId: context.tenantId,
        linkedid,
        queueName,
        eventType,
        eventTime,
        waitSeconds: Number(message.holdtime || message.waittime || 0),
        ringSeconds: Number(message.ringtime || message.origposition || 0),
        positionNo: Number(message.position || 0) || null,
        rawPayload: message as any,
      },
    });

    if (message.event === 'QueueCallerLeave' && message.reason?.toUpperCase() === 'ABANDON') {
      abandonFlag = true;
      nextStatus = SessionStatus.ENDED;
    }

    const updated = await this.prisma.callSession.update({
      where: { id: session.id },
      data: {
        queueName,
        queuedAt: message.event === 'QueueCallerJoin' ? eventTime : undefined,
        ringingAt: message.event === 'AgentCalled' ? eventTime : undefined,
        answeredAt: message.event === 'AgentConnect' ? eventTime : undefined,
        sessionStatus: nextStatus ?? undefined,
        abandonFlag,
        waitSeconds:
          message.event === 'AgentConnect'
            ? Number(message.holdtime || session.waitSeconds || 0)
            : undefined,
      },
    });

    const queueSummary = await this.queueSummaryService.getOne(queueName);

    return {
      broadcast: await this.snapshot(updated.id),
      queueSummary,
    };
  }

  private async handleBridgeEvent(
    message: AmiMessage,
    context: AmiEventContext,
    eventTime: Date,
    linkedid: string | null,
  ) {
    if (!linkedid) return null;

    if (message.event === 'BridgeEnter') {
      const session = await this.prisma.callSession.update({
        where: { linkedid },
        data: {
          sessionStatus: SessionStatus.TALKING,
          answeredAt: eventTime,
        },
      });
      return this.snapshotBroadcast(session.id);
    }

    if (message.event === 'BridgeLeave') {
      const session = await this.prisma.callSession.findUniqueOrThrow({
        where: { linkedid },
      });

      if (session.answeredAt) {
        const talkSeconds = Math.max(
          0,
          Math.floor((eventTime.getTime() - session.answeredAt.getTime()) / 1000),
        );

        await this.prisma.callSession.update({
          where: { id: session.id },
          data: { talkSeconds },
        });
      }
    }

    return null;
  }

  private async handleHoldEvent(
    message: AmiMessage,
    context: AmiEventContext,
    eventTime: Date,
    linkedid: string | null,
  ) {
    if (!linkedid) return null;

    const nextStatus =
      message.event === 'Hold' ? SessionStatus.HOLD : SessionStatus.TALKING;

    const session = await this.prisma.callSession.update({
      where: { linkedid },
      data: {
        sessionStatus: nextStatus,
      },
    });

    return this.snapshotBroadcast(session.id);
  }

  private async handleHangup(
    message: AmiMessage,
    context: AmiEventContext,
    eventTime: Date,
    linkedid: string | null,
  ) {
    if (!message.uniqueid) return null;

    const leg = await this.prisma.callLeg.findUnique({
      where: { uniqueid: message.uniqueid },
    });

    if (leg) {
      await this.prisma.callLeg.update({
        where: { uniqueid: message.uniqueid },
        data: {
          endedAt: eventTime,
          durationSeconds: Math.max(
            0,
            Math.floor((eventTime.getTime() - leg.startedAt.getTime()) / 1000),
          ),
          disposition: message.causeTxt || message.cause,
        },
      });
    }

    if (!linkedid) return null;

    const session = await this.prisma.callSession.findUniqueOrThrow({
      where: { linkedid },
    });

    const talkSeconds =
      session.answeredAt
        ? Math.max(0, Math.floor((eventTime.getTime() - session.answeredAt.getTime()) / 1000))
        : session.talkSeconds;

    const ended = await this.prisma.callSession.update({
      where: { id: session.id },
      data: {
        endedAt: eventTime,
        talkSeconds,
        sessionStatus: SessionStatus.ENDED,
        resultCode: session.abandonFlag ? 'ABANDONED' : 'COMPLETED',
      },
    });

    return this.snapshotBroadcast(ended.id, true);
  }

  private async handleTransfer(
    message: AmiMessage,
    context: AmiEventContext,
    eventTime: Date,
    linkedid: string | null,
    kind: TransferType,
  ) {
    if (!linkedid) return null;

    const session = await this.prisma.callSession.findUniqueOrThrow({
      where: { linkedid },
    });

    const fromExtension =
      this.extractAgentExtension(message) ||
      extractEndpointFromChannel(message.channel) ||
      null;

    const toExtension =
      message.extension ||
      message.target ||
      message.destexten ||
      extractEndpointFromChannel(message.destchannel) ||
      null;

    await this.prisma.callTransfer.create({
      data: {
        callId: session.id,
        tenantId: context.tenantId,
        linkedid,
        transferType: kind,
        fromExtension: fromExtension ?? undefined,
        toExtension: toExtension ?? undefined,
        transferResult: 'requested',
        requestedAt: eventTime,
      },
    });

    const updated = await this.prisma.callSession.update({
      where: { id: session.id },
      data: {
        transferFlag: true,
        sessionStatus: SessionStatus.TRANSFERRING,
      },
    });

    return this.snapshotBroadcast(updated.id);
  }

  private extractAgentExtension(message: AmiMessage): string | null {
    return (
      message.interface?.match(/\/(\d+)(?:@|$)/)?.[1] ??
      message.membername?.match(/(\d+)/)?.[1] ??
      extractEndpointFromChannel(message.channel) ??
      null
    );
  }

  private async snapshotBroadcast(callId: string, ended = false) {
    return {
      broadcast: await this.snapshot(callId, ended),
    };
  }

  private async snapshot(callId: string, ended = false) {
    const call = await this.prisma.callSession.findUniqueOrThrow({
      where: { id: callId },
      include: {
        legs: {
          orderBy: { startedAt: 'asc' },
        },
        transfers: {
          orderBy: { requestedAt: 'desc' },
        },
      },
    });

    return {
      type: ended ? 'call.ended' : 'call.updated',
      payload: call,
    };
  }
}
```

핵심 포인트는 `uniqueid`보다 `linkedid` 중심으로 세션을 유지하고, Queue 이벤트와 원본 raw 이벤트를 분리 저장하는 것입니다. 이건 상세 설계서와 산출물 문서의 중심 원칙과 동일합니다. fileciteturn2file0 fileciteturn2file1

