# 7) Queue Summary Service

## `src/queues/queue-summary.service.ts`

```ts
import { Injectable } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { SessionStatus } from '@prisma/client';

@Injectable()
export class QueueSummaryService {
  constructor(private readonly prisma: PrismaService) {}

  async getAll() {
    const queueNames = await this.prisma.callSession.findMany({
      where: {
        queueName: { not: null },
      },
      select: { queueName: true },
      distinct: ['queueName'],
    });

    const summaries = await Promise.all(
      queueNames
        .map((v) => v.queueName)
        .filter((v): v is string => !!v)
        .map((queueName) => this.getOne(queueName)),
    );

    return summaries.sort((a, b) => a.queueName.localeCompare(b.queueName));
  }

  async getOne(queueName: string) {
    const now = new Date();

    const active = await this.prisma.callSession.findMany({
      where: {
        queueName,
        sessionStatus: {
          in: [
            SessionStatus.QUEUED,
            SessionStatus.RINGING_AGENT,
            SessionStatus.TALKING,
            SessionStatus.HOLD,
            SessionStatus.TRANSFERRING,
            SessionStatus.AFTER_CALL_WORK,
          ],
        },
      },
      select: {
        id: true,
        sessionStatus: true,
        queuedAt: true,
        ringingAt: true,
        answeredAt: true,
        primaryAgentId: true,
      },
    });

    const todayStart = new Date(now);
    todayStart.setHours(0, 0, 0, 0);

    const [answeredToday, abandonedToday, completedToday] = await Promise.all([
      this.prisma.queueEvent.count({
        where: {
          queueName,
          eventType: 'AGENT_CONNECT',
          eventTime: { gte: todayStart },
        },
      }),
      this.prisma.callSession.count({
        where: {
          queueName,
          abandonFlag: true,
          startedAt: { gte: todayStart },
        },
      }),
      this.prisma.callSession.count({
        where: {
          queueName,
          sessionStatus: 'ENDED',
          abandonFlag: false,
          startedAt: { gte: todayStart },
        },
      }),
    ]);

    const waitingCount = active.filter((v) => v.sessionStatus === 'QUEUED').length;
    const ringingCount = active.filter((v) => v.sessionStatus === 'RINGING_AGENT').length;
    const talkingCount = active.filter((v) =>
      ['TALKING', 'HOLD', 'TRANSFERRING'].includes(v.sessionStatus),
    ).length;
    const acwCount = active.filter((v) => v.sessionStatus === 'AFTER_CALL_WORK').length;

    const queuedDurations = active
      .filter((v) => v.sessionStatus === 'QUEUED' && v.queuedAt)
      .map((v) => Math.floor((now.getTime() - (v.queuedAt as Date).getTime()) / 1000));

    const longestWaitSeconds = queuedDurations.length ? Math.max(...queuedDurations) : 0;

    return {
      queueName,
      waitingCount,
      ringingCount,
      talkingCount,
      acwCount,
      activeCallCount: active.length,
      answeredToday,
      abandonedToday,
      completedToday,
      longestWaitSeconds,
      updatedAt: now.toISOString(),
    };
  }
}
