# 12) Transfer / Hangup Command Service

## `src/calls/call-command.service.ts`

```ts
import { BadRequestException, Injectable } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { AmiClient } from '../ami/ami.client';
import { TransferCallDto } from './dto/transfer-call.dto';

@Injectable()
export class CallCommandService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly amiClient: AmiClient,
  ) {}

  async transfer(callId: string, dto: TransferCallDto) {
    const call = await this.prisma.callSession.findUnique({
      where: { id: callId },
      include: {
        legs: {
          where: { endedAt: null },
          orderBy: { startedAt: 'desc' },
        },
      },
    });

    if (!call) {
      throw new BadRequestException('Call not found');
    }

    const activeLeg = call.legs.find((leg) => !!leg.channelName);
    if (!activeLeg?.channelName) {
      throw new BadRequestException('Active channel not found');
    }

    let context = 'from-transfer';
    let exten = dto.target;

    if (dto.targetType === 'queue') {
      context = 'queue-entry';
    }

    if (dto.transferType === 'blind') {
      return this.amiClient.redirect({
        channel: activeLeg.channelName,
        context,
        exten,
        priority: 1,
      });
    }

    if (dto.transferType === 'attended') {
      return this.amiClient.originate({
        channel: `PJSIP/${dto.target}`,
        context: 'attended-transfer-bridge',
        exten: call.linkedid,
        priority: 1,
        async: true,
        variable: {
          ORIGINAL_LINKEDID: call.linkedid,
          ORIGINAL_CHANNEL: activeLeg.channelName,
          TARGET_EXTEN: dto.target,
        },
      });
    }

    throw new BadRequestException('Unsupported transfer type');
  }

  async hangup(callId: string) {
    const call = await this.prisma.callSession.findUnique({
      where: { id: callId },
      include: {
        legs: {
          where: { endedAt: null },
          orderBy: { startedAt: 'desc' },
        },
      },
    });

    if (!call) {
      throw new BadRequestException('Call not found');
    }

    const activeLeg = call.legs.find((leg) => !!leg.channelName);
    if (!activeLeg?.channelName) {
      throw new BadRequestException('Active channel not found');
    }

    return this.amiClient.hangup(activeLeg.channelName);
  }
}
```

