import {
  WebSocketGateway,
  WebSocketServer,
} from '@nestjs/websockets';
import { Server } from 'socket.io';

@WebSocketGateway({
  namespace: '/ws/agent',
  cors: { origin: '*' },
})
export class RealtimeGateway {
  @WebSocketServer()
  server!: Server;

  broadcastCallUpdated(data: unknown): void {
    const payload = data as any;
    this.server.emit(payload.type ?? 'call.updated', payload.payload ?? payload);
  }

  broadcastQueueSummaryUpdated(data: unknown): void {
    this.server.emit('queue.summary.updated', data);
  }

  broadcastAgentStatusChanged(data: unknown): void {
    this.server.emit('agent.status.changed', data);
  }
}
