# 📦 6. Session Engine (핵심)

```ts
import { Injectable } from '@nestjs/common';
import { SessionRepository } from './session.repository';

@Injectable()
export class SessionEngine {
  constructor(private repo: SessionRepository) {}

  async handleEvent(e: any) {
    const linkedid = e.Linkedid;

    switch (e.Event) {
      case 'QueueCallerJoin':
        await this.repo.upsertSession(linkedid, {
          session_status: 'QUEUED',
        });
        break;

      case 'AgentCalled':
        await this.repo.updateSession(linkedid, {
          session_status: 'RINGING_AGENT',
        });
        break;

      case 'BridgeEnter':
        await this.repo.updateSession(linkedid, {
          session_status: 'TALKING',
        });
        break;

      case 'Hangup':
        await this.repo.updateSession(linkedid, {
          session_status: 'ENDED',
        });
        break;
