## 5) `src/infra/leader-election/ami-leader-election.service.ts`

AMI 이벤트 소비는 **한 노드만 활성 리더**가 되도록 구성합니다. 설계서의 “AMI 재접속 후 재동기화”와 “이벤트 순서 역전 대비 idempotent 처리”를 운영형으로 만들기 위한 기본 전제입니다. fileciteturn0file1L119-L124

```ts
import {
  Injectable,
  Logger,
  OnModuleDestroy,
  OnModuleInit,
} from '@nestjs/common';
import { randomUUID } from 'crypto';
import { RedisService } from '../redis/redis.service';
import { REDIS_KEYS } from '../redis/redis.constants';

@Injectable()
export class AmiLeaderElectionService
  implements OnModuleInit, OnModuleDestroy
{
  private readonly logger = new Logger(AmiLeaderElectionService.name);
  private readonly instanceId =
    process.env.INSTANCE_ID ?? `${process.pid}-${randomUUID()}`;
  private readonly ttlSeconds = Number(
    process.env.AMI_LEADER_LOCK_TTL_SECONDS ?? 10,
  );
  private readonly renewIntervalMs = Number(
    process.env.AMI_LEADER_RENEW_INTERVAL_MS ?? 3000,
  );

  private renewTimer?: NodeJS.Timeout;
  private leader = false;

  constructor(private readonly redisService: RedisService) {}

  async onModuleInit(): Promise<void> {
    await this.tryAcquireLeadership();
    this.renewTimer = setInterval(async () => {
      await this.heartbeat();
    }, this.renewIntervalMs);
  }

  async onModuleDestroy(): Promise<void> {
    if (this.renewTimer) clearInterval(this.renewTimer);
    await this.releaseIfLeader();
  }

  getInstanceId(): string {
    return this.instanceId;
  }

  isLeader(): boolean {
    return this.leader;
  }

  private async tryAcquireLeadership(): Promise<void> {
    const result = await this.redisService.set(
      REDIS_KEYS.amiLeader,
      this.instanceId,
      this.ttlSeconds,
      true,
    );

    if (result === 'OK') {
      this.leader = true;
      this.logger.log(`AMI leader acquired by ${this.instanceId}`);
      await this.redisService.set(
        REDIS_KEYS.leaderHeartbeat,
        JSON.stringify({
          instanceId: this.instanceId,
          ts: new Date().toISOString(),
        }),
        this.ttlSeconds,
      );
      return;
    }

    const current = await this.redisService.get(REDIS_KEYS.amiLeader);
    this.leader = current === this.instanceId;
  }

  private async heartbeat(): Promise<void> {
    if (!this.leader) {
      await this.tryAcquireLeadership();
      return;
    }

    const script = `
      if redis.call("GET", KEYS[1]) == ARGV[1] then
        redis.call("EXPIRE", KEYS[1], ARGV[2])
        return 1
      else
        return 0
      end
    `;

    const renewed = await this.redisService.eval(script, [REDIS_KEYS.amiLeader], [
      this.instanceId,
      String(this.ttlSeconds),
    ]);

    if (Number(renewed) === 1) {
      await this.redisService.set(
        REDIS_KEYS.leaderHeartbeat,
        JSON.stringify({
          instanceId: this.instanceId,
          ts: new Date().toISOString(),
        }),
        this.ttlSeconds,
      );
      return;
    }

    this.leader = false;
    this.logger.warn(`AMI leadership lost by ${this.instanceId}`);
    await this.tryAcquireLeadership();
  }

  async releaseIfLeader(): Promise<void> {
    const script = `
      if redis.call("GET", KEYS[1]) == ARGV[1] then
        return redis.call("DEL", KEYS[1])
      else
        return 0
      end
    `;

    try {
      await this.redisService.eval(script, [REDIS_KEYS.amiLeader], [
        this.instanceId,
      ]);
    } finally {
      this.leader = false;
    }
  }
}
```

