## 6) `src/events/event-bus.service.ts`

DB Outbox + Redis fanout 조합입니다.  
리더 노드는 AMI를 읽고 DB에 정규화/Outbox를 적재하고, 모든 노드는 Redis Pub/Sub로 UI 브로드캐스트를 수신합니다.

```ts
import {
  Injectable,
  Logger,
  OnModuleDestroy,
  OnModuleInit,
} from '@nestjs/common';
import { REDIS_KEYS } from '../infra/redis/redis.constants';
import { RedisService } from '../infra/redis/redis.service';

export interface DomainEventEnvelope<T = unknown> {
  id: string;
  type: string;
  occurredAt: string;
  tenantId?: string | null;
  entityType?: string | null;
  entityId?: string | null;
  payload: T;
}

@Injectable()
export class EventBusService implements OnModuleInit, OnModuleDestroy {
  private readonly logger = new Logger(EventBusService.name);
  private subscriber?: ReturnType<RedisService['client']['duplicate']>;

  constructor(private readonly redisService: RedisService) {}

  async onModuleInit(): Promise<void> {
    this.subscriber = await this.redisService.duplicateSubscriber();
  }

  async onModuleDestroy(): Promise<void> {
    if (!this.subscriber) return;
    try {
      await this.subscriber.quit();
    } catch {
      this.subscriber.disconnect();
    }
  }

  async publish(event: DomainEventEnvelope): Promise<void> {
    await this.redisService.publish(REDIS_KEYS.wsFanout, JSON.stringify(event));
  }

  async subscribe(
    handler: (event: DomainEventEnvelope) => Promise<void> | void,
  ): Promise<void> {
    if (!this.subscriber) {
      this.subscriber = await this.redisService.duplicateSubscriber();
    }

    await this.subscriber.subscribe(REDIS_KEYS.wsFanout);
    this.subscriber.on('message', async (channel, message) => {
      if (channel !== REDIS_KEYS.wsFanout) return;

      try {
        const event = JSON.parse(message) as DomainEventEnvelope;
        await handler(event);
      } catch (error) {
        this.logger.error('Failed to handle subscribed event', error as Error);
      }
    });
  }
}
```

