## 7) `src/events/outbox-publisher.service.ts`

정규화 트랜잭션 안에서 `event_outbox`에 쌓인 이벤트를 꺼내 Redis Pub/Sub로 발행합니다.

```ts
import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { EventBusService, DomainEventEnvelope } from './event-bus.service';

@Injectable()
export class OutboxPublisherService {
  private readonly logger = new Logger(OutboxPublisherService.name);
  private readonly batchSize = Number(
    process.env.OUTBOX_PUBLISH_BATCH_SIZE ?? 100,
  );

  constructor(
    private readonly prisma: PrismaService,
    private readonly eventBus: EventBusService,
  ) {}

  async publishPending(): Promise<number> {
    const rows = await this.prisma.eventOutbox.findMany({
      where: {
        publishedAt: null,
        lockedAt: null,
      },
      orderBy: { createdAt: 'asc' },
      take: this.batchSize,
    });

    if (rows.length === 0) return 0;

    let publishedCount = 0;

    for (const row of rows) {
      const lock = await this.prisma.eventOutbox.updateMany({
        where: {
          id: row.id,
          publishedAt: null,
          lockedAt: null,
        },
        data: {
          lockedAt: new Date(),
          lockOwner: process.env.INSTANCE_ID ?? String(process.pid),
        },
      });

      if (lock.count === 0) continue;

      try {
        const envelope: DomainEventEnvelope = {
          id: row.id,
          type: row.eventType,
          occurredAt: row.occurredAt.toISOString(),
          tenantId: row.tenantId,
          entityType: row.aggregateType,
          entityId: row.aggregateId,
          payload: row.payload as Record<string, unknown>,
        };

        await this.eventBus.publish(envelope);

        await this.prisma.eventOutbox.update({
          where: { id: row.id },
          data: {
            publishedAt: new Date(),
            publishAttempts: { increment: 1 },
            lastError: null,
          },
        });

        publishedCount += 1;
      } catch (error) {
        this.logger.error(
          `Failed to publish outbox event ${row.id}`,
          error as Error,
        );

        await this.prisma.eventOutbox.update({
          where: { id: row.id },
          data: {
            lockedAt: null,
            lockOwner: null,
            publishAttempts: { increment: 1 },
            lastError:
              error instanceof Error ? error.message.slice(0, 1000) : 'unknown',
          },
        });
      }
    }

    return publishedCount;
  }
}
```

