## 10) `src/recovery/call-finalizer.service.ts`

`Hangup`만으로 즉시 종결하지 않고, **짧은 유예 시간 후 최종 판정**합니다.  
이유는 attended transfer, late AgentComplete, 순서 역전 이벤트 때문에 바로 ENDED 처리하면 오판정이 생기기 때문입니다. 이는 상세 설계서의 **linkedid 중심 세션 상태머신**과 **이벤트 순서 역전 대응** 원칙에 맞춘 구현입니다. fileciteturn0file1L105-L124

```ts
import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';

@Injectable()
export class CallFinalizerService {
  private readonly logger = new Logger(CallFinalizerService.name);
  private readonly finalizeDelaySeconds = Number(
    process.env.CALL_FINALIZE_DELAY_SECONDS ?? 15,
  );

  constructor(private readonly prisma: PrismaService) {}

  async finalizeCandidates(): Promise<number> {
    const threshold = new Date(Date.now() - this.finalizeDelaySeconds * 1000);

    const sessions = await this.prisma.callSession.findMany({
      where: {
        endedAt: null,
        finalizeRequestedAt: { lte: threshold, not: null },
        sessionStatus: {
          in: ['TALKING', 'HOLD', 'TRANSFERRING', 'AFTER_CALL_WORK', 'RINGING_AGENT', 'QUEUED'],
        },
      },
      take: 200,
      orderBy: { finalizeRequestedAt: 'asc' },
      include: {
        legs: true,
      },
    });

    let count = 0;

    for (const session of sessions) {
      const activeLegExists = session.legs.some((leg) => !leg.endedAt);

      if (activeLegExists) {
        continue;
      }

      const endedAt =
        session.lastBridgeLeftAt ??
        session.lastHangupAt ??
        session.updatedAt ??
        new Date();

      const answeredAt = session.answeredAt;
      const talkSeconds =
        answeredAt != null
          ? Math.max(
              0,
              Math.floor((endedAt.getTime() - answeredAt.getTime()) / 1000),
            )
          : session.talkSeconds;

      await this.prisma.callSession.update({
        where: { callId: session.callId },
        data: {
          sessionStatus: 'ENDED',
          endedAt,
          talkSeconds,
          recoveryRequired: false,
          finalizeRequestedAt: null,
          updatedAt: new Date(),
        },
      });

      await this.prisma.eventOutbox.create({
        data: {
          tenantId: session.tenantId,
          aggregateType: 'call_session',
          aggregateId: session.callId,
          eventType: 'call.ended',
          occurredAt: new Date(),
          payload: {
            callId: session.callId,
            linkedid: session.linkedid,
            endedAt: endedAt.toISOString(),
            talkSeconds,
            sessionStatus: 'ENDED',
          },
        },
      });

      count += 1;
    }

    if (count > 0) {
      this.logger.log(`Finalized ${count} call sessions`);
    }

    return count;
  }
}
