## 11) `src/recovery/orphan-session-sweeper.service.ts`

유령 세션 정리용 스위퍼입니다.  
설계서의 “장시간 남은 유령 세션은 타임아웃 정리”를 그대로 반영합니다. fileciteturn0file1L121-L124

```ts
import { Injectable, Logger } from '@nestjs/common';
import { Cron, CronExpression } from '@nestjs/schedule';
import { PrismaService } from '../prisma/prisma.service';
import { CallFinalizerService } from './call-finalizer.service';

@Injectable()
export class OrphanSessionSweeperService {
  private readonly logger = new Logger(OrphanSessionSweeperService.name);
  private readonly staleMinutes = Number(
    process.env.ORPHAN_SESSION_STALE_MINUTES ?? 30,
  );

  constructor(
    private readonly prisma: PrismaService,
    private readonly finalizer: CallFinalizerService,
  ) {}

  @Cron(CronExpression.EVERY_MINUTE)
  async sweep(): Promise<void> {
    const staleThreshold = new Date(
      Date.now() - this.staleMinutes * 60 * 1000,
    );

    const staleSessions = await this.prisma.callSession.findMany({
      where: {
        endedAt: null,
        updatedAt: { lte: staleThreshold },
        sessionStatus: {
          not: 'ENDED',
        },
      },
      take: 200,
      orderBy: { updatedAt: 'asc' },
    });

    if (staleSessions.length === 0) {
      await this.finalizer.finalizeCandidates();
      return;
    }

    for (const session of staleSessions) {
      await this.prisma.callSession.update({
        where: { callId: session.callId },
        data: {
          finalizeRequestedAt: new Date(),
          resultCode: session.resultCode ?? 'ORPHAN_TIMEOUT',
          resultDetail: session.resultDetail ?? 'Sweeper requested finalize',
          updatedAt: new Date(),
        },
      });
    }

    this.logger.warn(
      `Marked ${staleSessions.length} orphan sessions for finalization`,
    );

    await this.finalizer.finalizeCandidates();
  }
}
```

