import { Controller, Get } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { RedisService } from '../infra/redis/redis.service';
import { AmiLeaderElectionService } from '../infra/leader-election/ami-leader-election.service';

@Controller('health')
export class HealthController {
  constructor(
    private readonly prisma: PrismaService,
    private readonly redisService: RedisService,
    private readonly amiLeaderElectionService: AmiLeaderElectionService,
  ) {}

  @Get()
  async health() {
    const now = new Date().toISOString();

    const [dbOk, redisPing] = await Promise.all([
      this.prisma.$queryRawUnsafe('SELECT 1 as ok'),
      this.redisService.ping(),
    ]);

    return {
      success: true,
      data: {
        status: 'ok',
        timestamp: now,
        instanceId: this.amiLeaderElectionService.getInstanceId(),
        leader: this.amiLeaderElectionService.isLeader(),
        checks: {
          db: Array.isArray(dbOk) ? 'up' : 'up',
          redis: redisPing === 'PONG' ? 'up' : 'degraded',
        },
      },
      error: null,
    };
  }

  @Get('ready')
  async readiness() {
    await this.prisma.$queryRawUnsafe('SELECT 1');
    await this.redisService.ping();

    return {
      success: true,
      data: {
        ready: true,
      },
      error: null,
    };
  }

  @Get('live')
  liveness() {
    return {
      success: true,
      data: {
        alive: true,
      },
      error: null,
    };
  }
}
