## 16) `prisma/migrations/20260414_operational_cti_runtime/migration.sql`

아래 SQL은 기존 CTI 스키마에 **운영형 런타임 컬럼 + event_outbox + 처리 인덱스**를 추가하는 형태입니다.  
기존 설계 문서의 `call_sessions`, `call_legs`, `raw_ami_events`, `queue_events`를 기준으로 확장했습니다. fileciteturn0file2L118-L134

```sql
-- =========================================================
-- Operational runtime extension for NestJS + Prisma CTI
-- =========================================================

CREATE EXTENSION IF NOT EXISTS "pgcrypto";
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- ---------------------------------------------------------
-- call_sessions operational columns
-- ---------------------------------------------------------
ALTER TABLE call_sessions
  ADD COLUMN IF NOT EXISTS recovery_required BOOLEAN NOT NULL DEFAULT FALSE,
  ADD COLUMN IF NOT EXISTS recovery_marked_at TIMESTAMPTZ NULL,
  ADD COLUMN IF NOT EXISTS finalize_requested_at TIMESTAMPTZ NULL,
  ADD COLUMN IF NOT EXISTS last_hangup_at TIMESTAMPTZ NULL,
  ADD COLUMN IF NOT EXISTS last_bridge_left_at TIMESTAMPTZ NULL,
  ADD COLUMN IF NOT EXISTS last_event_at TIMESTAMPTZ NULL,
  ADD COLUMN IF NOT EXISTS version_no INTEGER NOT NULL DEFAULT 0;

CREATE INDEX IF NOT EXISTS idx_call_sessions_recovery_required
  ON call_sessions(recovery_required, updated_at DESC)
  WHERE ended_at IS NULL;

CREATE INDEX IF NOT EXISTS idx_call_sessions_finalize_requested_at
  ON call_sessions(finalize_requested_at)
  WHERE ended_at IS NULL;

CREATE INDEX IF NOT EXISTS idx_call_sessions_last_event_at
  ON call_sessions(last_event_at DESC);

-- ---------------------------------------------------------
-- call_legs operational columns
-- ---------------------------------------------------------
ALTER TABLE call_legs
  ADD COLUMN IF NOT EXISTS last_event_at TIMESTAMPTZ NULL,
  ADD COLUMN IF NOT EXISTS hangup_cause VARCHAR(64) NULL,
  ADD COLUMN IF NOT EXISTS hangup_cause_txt VARCHAR(255) NULL;

CREATE INDEX IF NOT EXISTS idx_call_legs_linkedid_ended_at
  ON call_legs(linkedid, ended_at);

CREATE INDEX IF NOT EXISTS idx_call_legs_last_event_at
  ON call_legs(last_event_at DESC);

-- ---------------------------------------------------------
-- raw_ami_events dedupe / replay support
-- ---------------------------------------------------------
ALTER TABLE raw_ami_events
  ADD COLUMN IF NOT EXISTS dedupe_key VARCHAR(255) NULL,
  ADD COLUMN IF NOT EXISTS processed_at TIMESTAMPTZ NULL,
  ADD COLUMN IF NOT EXISTS processing_status VARCHAR(16) NOT NULL DEFAULT 'PENDING',
  ADD COLUMN IF NOT EXISTS processing_error TEXT NULL;

CREATE INDEX IF NOT EXISTS idx_raw_ami_events_processing_status
  ON raw_ami_events(processing_status, event_time);

CREATE INDEX IF NOT EXISTS idx_raw_ami_events_dedupe_key
  ON raw_ami_events(dedupe_key);

-- ---------------------------------------------------------
-- event outbox
-- ---------------------------------------------------------
CREATE TABLE IF NOT EXISTS event_outbox (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NULL REFERENCES tenants(tenant_id),
  aggregate_type VARCHAR(64) NOT NULL,
  aggregate_id VARCHAR(64) NOT NULL,
  event_type VARCHAR(128) NOT NULL,
  payload JSONB NOT NULL,
  occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  locked_at TIMESTAMPTZ NULL,
  lock_owner VARCHAR(128) NULL,
  published_at TIMESTAMPTZ NULL,
  publish_attempts INTEGER NOT NULL DEFAULT 0,
  last_error TEXT NULL
);

CREATE INDEX IF NOT EXISTS idx_event_outbox_publish_pending
  ON event_outbox(published_at, locked_at, created_at);

CREATE INDEX IF NOT EXISTS idx_event_outbox_aggregate
  ON event_outbox(aggregate_type, aggregate_id, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_event_outbox_event_type
  ON event_outbox(event_type, created_at DESC);

-- ---------------------------------------------------------
-- session recovery snapshot queue (optional but practical)
-- ---------------------------------------------------------
CREATE TABLE IF NOT EXISTS session_recovery_jobs (
  job_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NULL REFERENCES tenants(tenant_id),
  linkedid VARCHAR(32) NOT NULL,
  call_id UUID NULL REFERENCES call_sessions(call_id) ON DELETE CASCADE,
  job_type VARCHAR(32) NOT NULL
    CHECK (job_type IN ('AMI_RESYNC', 'FINALIZE', 'ORPHAN_SWEEP')),
  status VARCHAR(16) NOT NULL DEFAULT 'PENDING'
    CHECK (status IN ('PENDING', 'RUNNING', 'DONE', 'FAILED')),
  requested_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  started_at TIMESTAMPTZ NULL,
  completed_at TIMESTAMPTZ NULL,
  retry_count INTEGER NOT NULL DEFAULT 0,
  error_message TEXT NULL
);

CREATE INDEX IF NOT EXISTS idx_session_recovery_jobs_status
  ON session_recovery_jobs(status, requested_at);

CREATE INDEX IF NOT EXISTS idx_session_recovery_jobs_linkedid
  ON session_recovery_jobs(linkedid, requested_at DESC);

-- ---------------------------------------------------------
-- queue_events operational indexes
-- ---------------------------------------------------------
CREATE INDEX IF NOT EXISTS idx_queue_events_call_id
  ON queue_events(call_id, event_time DESC);

CREATE INDEX IF NOT EXISTS idx_queue_events_agent_id
  ON queue_events(agent_id, event_time DESC);

-- ---------------------------------------------------------
-- useful comments
-- ---------------------------------------------------------
COMMENT ON TABLE event_outbox IS 'Transactional outbox for websocket/admin fanout';
COMMENT ON COLUMN call_sessions.recovery_required IS 'Marked true after leader failover or AMI reconnect requiring reconciliation';
COMMENT ON COLUMN call_sessions.finalize_requested_at IS 'Delayed finalization trigger to avoid premature end during transfer or late queue events';
